PROCESSING_ACTIVE_STATUSES = {"running", "processing", "analyzing", "cancelling"}
PROCESSING_TIMING_VERSION = 1


def _finite_progress_number(value: Any) -> float | None:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if math.isfinite(number) else None


def progress_facts_snapshot(job: dict[str, Any]) -> dict[str, Any]:
    """Build a stable, presentation-neutral progress contract.

    ``workflow.fraction`` is the weighted pipeline completion already used by
    the application. ``stage`` only becomes determinate when the worker has a
    measured numerator and denominator. Remote model heartbeats therefore
    remain active without inventing an internal percentage.
    """
    stage_id = str(job.get("stage") or "queued")
    status = str(job.get("status") or "")
    progress_mode = str(job.get("progressMode") or "indeterminate")
    eta_mode = str(job.get("etaMode") or "collecting")
    overall = _finite_progress_number(job.get("progress"))
    overall = max(0.0, min(1.0, overall if overall is not None else 0.0))
    completed = _finite_progress_number(job.get("stageCompleted"))
    total = _finite_progress_number(job.get("stageTotal"))
    completed_seconds = _finite_progress_number(job.get("stageCompletedSeconds"))
    total_seconds = _finite_progress_number(job.get("stageTotalSeconds"))
    stage_fraction = _finite_progress_number(job.get("stageProgress"))
    counted = total is not None and total > 0 and completed is not None
    timed = total_seconds is not None and total_seconds > 0 and completed_seconds is not None
    measurable = (
        progress_mode == "determinate"
        and stage_fraction is not None
        and (counted or timed)
    )
    if status == "completed" or eta_mode == "completed" or stage_id in {"completed", "awaiting_confirmation", "content_search_ready", "edit_planning_complete"}:
        mode = "completed"
    elif eta_mode in {"finalizing", "quality_check"} or progress_mode == "finalizing":
        mode = "finalizing"
    elif measurable:
        mode = "determinate"
    else:
        mode = "indeterminate"

    if stage_id in {"rendering", "render", "edit_planning", "auto_composition"}:
        workflow_phase = 2
    elif stage_id in {
        "audio_analysis", "speech_recognition", "speech_analysis", "sampling",
        "content_classification", "coarse_vlm", "refine_vlm", "event_grouping",
        "event_director", "awaiting_confirmation", "content_transcription", "content_sampling",
        "content_indexing", "content_recognition", "content_index_ready", "content_search",
        "content_person_description", "content_active_speaker", "content_refinement",
        "content_search_ready",
    }:
        workflow_phase = 1
    else:
        workflow_phase = 0
    if status == "completed":
        workflow_phase = 3
    elif mode == "completed" and overall >= 1.0:
        workflow_phase = 3

    stage_elapsed_seconds = None
    stage_started_raw = str(job.get("stageStartedAt") or "")
    if stage_started_raw:
        try:
            stage_started = datetime.fromisoformat(stage_started_raw.replace("Z", "+00:00"))
            stage_elapsed_seconds = max(0.0, (datetime.now(timezone.utc) - stage_started).total_seconds())
        except ValueError:
            stage_elapsed_seconds = None
    media_rate = (
        completed_seconds / stage_elapsed_seconds
        if completed_seconds is not None and completed_seconds > 0 and stage_elapsed_seconds
        else None
    )

    return {
        "schemaVersion": 1,
        "workflow": {
            "fraction": round(overall, 4),
            "completedSteps": max(0, min(3, workflow_phase)),
            "totalSteps": 3,
            "phase": ["prepare", "analysis", "output", "completed"][max(0, min(3, workflow_phase))],
        },
        "stage": {
            "id": stage_id,
            "label": PROGRESS_STAGE_LABELS.get(stage_id, stage_id.replace("_", " ") or "处理中"),
            "mode": mode,
            "phase": "finalizing" if mode == "finalizing" else ("completed" if mode == "completed" else "processing"),
            "fraction": round(max(0.0, min(1.0, stage_fraction)), 4) if measurable and stage_fraction is not None else None,
            # Finalization has no honest internal percentage, but completed
            # inference batches remain useful facts (for example 40/40).
            "completed": completed if counted else None,
            "total": total if counted else None,
            "unit": str(job.get("stageUnit") or ""),
            "completedSeconds": completed_seconds if timed else None,
            "totalSeconds": total_seconds if timed else None,
            "elapsedSeconds": round(stage_elapsed_seconds, 3) if stage_elapsed_seconds is not None else None,
            "mediaSecondsPerWallSecond": round(media_rate, 3) if media_rate is not None else None,
            "realTimeFactor": round(1 / media_rate, 3) if media_rate else None,
        },
        "timing": {
            "startedAt": job.get("startedAt") or job.get("createdAt"),
            "stageStartedAt": job.get("stageStartedAt"),
            "lastProgressAt": job.get("lastProgressAt") or job.get("updatedAt"),
            "etaSeconds": job.get("etaSeconds"),
            "etaMode": eta_mode,
            "processingElapsedSeconds": float(job.get("processingElapsedSeconds") or 0.0),
            "processingActiveSince": job.get("processingActiveSince"),
            "processingTimingVersion": int(job.get("processingTimingVersion") or PROCESSING_TIMING_VERSION),
        },
        "activity": {
            "model": str(job.get("model") or "系统"),
            "detail": str(job.get("currentAction") or job.get("detail") or PROGRESS_STAGE_LABELS.get(stage_id, "处理中")),
        },
    }


def _agent_plan_quality(plan: dict[str, Any]) -> dict[str, Any]:
    """Project the latest delivery QC artifact into a compact UI-safe shape."""
    steps = plan.get("steps") if isinstance(plan.get("steps"), list) else []
    artifact = next((
        (step.get("result") or {}).get("artifact")
        for step in steps
        if isinstance(step, dict)
        and isinstance(step.get("result"), dict)
        and isinstance((step.get("result") or {}).get("artifact"), dict)
        and str(((step.get("result") or {}).get("artifact") or {}).get("kind") or "")
        == "delivery_qc_report"
    ), None)
    if not isinstance(artifact, dict):
        checks = []
        for step in steps:
            result_artifact = (step.get("result") or {}).get("artifact") or {}
            for preview in [result_artifact, *(result_artifact.get("previews") or [])]:
                if isinstance(preview.get("contentVerification"), dict):
                    checks.append(preview["contentVerification"])
        if not checks:
            return {"status": "not_run", "passed": None, "issues": []}
        artifact = {"passed": all(c.get("passed") is True for c in checks), "reports": checks}

    issues: list[dict[str, Any]] = []
    for report in artifact.get("reports") or []:
        if not isinstance(report, dict):
            continue
        for issue in report.get("issues") or []:
            if not isinstance(issue, dict):
                continue
            evidence = issue.get("evidence") if isinstance(issue.get("evidence"), dict) else {}
            ranges = evidence.get("ranges") if isinstance(evidence.get("ranges"), list) else []
            issues.append({
                "severity": str(issue.get("severity") or "warning"),
                "code": str(issue.get("code") or "quality_issue"),
                "message": str(issue.get("message") or "发现需要复核的质量问题")[:500],
                "ranges": [
                    {
                        "start": max(0.0, float(item.get("start") or 0)),
                        "end": max(0.0, float(item.get("end") or 0)),
                        "duration": max(0.0, float(item.get("duration") or 0)),
                    }
                    for item in ranges[:20] if isinstance(item, dict)
                ],
            })
    has_error = any(issue["severity"] == "error" for issue in issues)
    has_warning = any(issue["severity"] == "warning" for issue in issues)
    passed = artifact.get("passed") is True
    status = "passed" if passed else "failed" if has_error or not issues else "warning" if has_warning else "failed"
    return {
        "status": status,
        "passed": passed,
        "strict": bool(artifact.get("strict")),
        "issues": issues,
    }


def _agent_plan_progress(plan: dict[str, Any] | None) -> dict[str, Any]:
    """Return a compact, job-safe projection of one Agent plan."""
    plan = plan if isinstance(plan, dict) else {}
    steps = plan.get("steps") if isinstance(plan.get("steps"), list) else []
    successful = sum(
        1 for step in steps
        if isinstance(step, dict) and str(step.get("status") or "") == "completed"
    )
    skipped = sum(
        1 for step in steps
        if isinstance(step, dict) and str(step.get("status") or "") == "skipped"
    )
    settled = sum(
        1 for step in steps
        if isinstance(step, dict) and str(step.get("status") or "") in {"completed", "skipped"}
    )
    failed = next((
        step for step in steps
        if isinstance(step, dict) and str(step.get("status") or "") == "failed"
    ), None)
    current = failed if str(plan.get("status") or "") == "failed" else next((
        step for step in steps
        if isinstance(step, dict) and str(step.get("status") or "")
        in {"running", "waiting_operation", "action_required"}
    ), None)
    if current is None:
        current = next((
            step for step in steps
            if isinstance(step, dict) and str(step.get("status") or "") == "pending"
        ), None)
    return {
        "planId": str(plan.get("id") or ""),
        "planHash": str(plan.get("planHash") or ""),
        "status": str(plan.get("status") or "planning"),
        "summary": str(plan.get("summary") or ""),
        "skillId": str(plan.get("skillId") or ""),
        # Keep completedSteps as the legacy settled count. New presentation
        # surfaces use the explicit successful/skipped/settled fields below.
        "completedSteps": settled,
        "successfulSteps": successful,
        "skippedSteps": skipped,
        "settledSteps": settled,
        "totalSteps": len(steps),
        "currentStepId": str((current or {}).get("id") or ""),
        "currentStepTitle": str((current or {}).get("title") or ""),
        "currentStepTool": str((current or {}).get("tool") or ""),
        "currentStepStatus": str((current or {}).get("status") or ""),
        "currentStepAction": str(((current or {}).get("result") or {}).get("action") or ""),
        "currentStepMessage": str(((current or {}).get("result") or {}).get("message") or "")[:500],
        "quality": _agent_plan_quality(plan),
    }


def _agent_autonomous_checkpoint_active(
    job: dict[str, Any], tools: set[str] | None = None,
) -> bool:
    """Return whether an autonomous Agent owns the current review checkpoint.

    Media workers normally finish discovery/search by publishing a user review
    state. In autonomous review that state belongs to the following Agent
    step, not to the user. Keeping this predicate on the durable job prevents
    polling clients from observing an incorrect confirmation gate between the
    worker Future completing and the Agent callback advancing.
    """
    agent = job.get("agent") if isinstance(job.get("agent"), dict) else {}
    if str(agent.get("executionMode") or "") != "autonomous_review":
        return False
    if str(agent.get("status") or "") not in {"approved", "running"}:
        return False
    current_tool = str(agent.get("currentStepTool") or "")
    return not tools or current_tool in tools


def _agent_review_previews_from_plan(
    plan: dict[str, Any] | None, job: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    """Extract review-sample artifacts from an Agent plan.

    Agent review samples are intentionally not formal output versions.  Keep
    them in a separate public list so the UI can show "审核样片" without
    implying that a downloadable高清成片 already exists.
    """
    if not isinstance(plan, dict):
        return []
    previews: list[dict[str, Any]] = []
    for step in plan.get("steps") or []:
        if not isinstance(step, dict):
            continue
        result = step.get("result") if isinstance(step.get("result"), dict) else {}
        artifact = result.get("artifact") if isinstance(result.get("artifact"), dict) else None
        if not artifact:
            continue
        raw_items: list[dict[str, Any]] = []
        kind = str(artifact.get("kind") or "")
        if kind == "review_preview_batch":
            raw_items = [item for item in artifact.get("previews") or [] if isinstance(item, dict)]
        elif kind == "review_preview" and isinstance(artifact.get("outputs"), list):
            raw_items = [item for item in artifact.get("outputs") or [] if isinstance(item, dict)]
        elif kind == "review_preview":
            raw_items = [artifact]
        for index, item in enumerate(raw_items, 1):
            preview_url = str(item.get("previewUrl") or item.get("videoUrl") or "").strip()
            filename = str(item.get("filename") or "").strip()
            session_id = str(item.get("sessionId") or item.get("sourceEditSessionId") or "").strip()
            revision = int(item.get("revision") or 0)
            if not preview_url and not filename and not session_id:
                continue
            stable_key = filename or preview_url or f"{session_id}:r{revision or 1}"
            digest = hashlib.sha1(stable_key.encode("utf-8")).hexdigest()[:12]
            session = next((
                value for value in (job or {}).get("editSessions") or []
                if isinstance(value, dict) and str(value.get("id") or "") == session_id
            ), None)
            clips = [value for value in (session or {}).get("clips") or [] if isinstance(value, dict)]
            segments = [{
                "id": str(clip.get("id") or f"preview_clip_{clip_index}"),
                "title": str(clip.get("title") or f"镜头 {clip_index}"),
                "role": str(clip.get("title") or f"镜头 {clip_index}"),
                "start": float(clip.get("sourceStart") or 0),
                "end": float(clip.get("sourceEnd") or clip.get("sourceStart") or 0),
                "duration": float(clip.get("duration") or 0),
                "playbackRate": float(clip.get("playbackRate") or 1),
                "transitionIn": copy.deepcopy(clip.get("transitionIn") or {"type": "cut", "duration": 0}),
                "audioBridge": copy.deepcopy(clip.get("audioBridge") or {"type": "none", "duration": 0}),
            } for clip_index, clip in enumerate(clips, 1)]
            preflight = (session or {}).get("preflight") if isinstance((session or {}).get("preflight"), dict) else None
            quality_status = ""
            if preflight is not None:
                errors = int(preflight.get("errorCount") or 0)
                warnings = int(preflight.get("unacknowledgedWarningCount") or preflight.get("warningCount") or 0)
                quality_status = "passed" if bool(preflight.get("ready")) and not errors and not warnings else "needs_review"
            content_check = item.get("contentVerification") or (session or {}).get("contentVerification") or {}
            if content_check.get("passed") is False:
                quality_status = "needs_review"
            preview = {
                "id": str(item.get("id") or f"agent_review_{digest}"),
                "kind": "review_preview",
                "outputKind": "agent_review_preview",
                "planId": plan.get("id"),
                "title": str(item.get("title") or f"审核样片 {index}"),
                "duration": float(item.get("duration") or (session or {}).get("duration") or 0),
                "previewUrl": preview_url,
                "videoUrl": preview_url,
                "filename": filename,
                "sessionId": session_id,
                "sourceEditSessionId": session_id,
                "revision": revision or None,
                "previewOnly": True,
                "message": str(item.get("message") or "低分辨率审核样片，正式导出需单独确认。"),
            }
            if session is not None:
                preview.update({
                    "clipCount": len(clips),
                    "segments": segments,
                    "timelineReady": bool(clips),
                    "previewStatus": str(session.get("previewStatus") or ""),
                    "overlayVerification": copy.deepcopy(session.get("previewOverlayVerification") or {}),
                    "subtitleMode": (
                        "burn"
                        if int((session.get("previewOverlayVerification") or {}).get("subtitleCueCount") or 0) > 0
                        else "none"
                    ),
                })
            if preflight is not None:
                preview["preflight"] = copy.deepcopy(preflight)
            if quality_status:
                preview["qualityStatus"] = quality_status
            previews.append(preview)
    seen: set[str] = set()
    unique: list[dict[str, Any]] = []
    for item in previews:
        key = str(item.get("filename") or item.get("previewUrl") or item.get("id") or "")
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(item)
    return unique


def sync_agent_workspace_to_job(
    workspace: dict[str, Any], plan: dict[str, Any] | None = None,
) -> None:
    """Mirror just enough Agent state into the task record for reload/polling.

    The complete plan remains in the Agent store.  This copy is intentionally
    small and lets task cards, job polling and a restored browser agree on the
    active workspace and the user's next action.
    """
    job_id = str(workspace.get("jobId") or "")
    if not job_id:
        return
    summary = _agent_plan_progress(plan)
    workspace_id = str(workspace.get("id") or "")
    plan_status = str(summary["status"])
    with jobs_lock:
        job = jobs.get(job_id)
        if not job:
            return
        review_previews = _agent_review_previews_from_plan(plan, job)
        previous_job_projection = (
            str(job.get("status") or ""), str(job.get("stage") or ""),
            str(job.get("detail") or ""), str(job.get("currentAction") or ""),
            float(job.get("progress") or 0), job.get("stageProgress"),
        )
        next_agent = {
            "workspaceId": workspace_id,
            "sourceJobId": str(workspace.get("sourceJobId") or ""),
            "workspaceStatus": str(workspace.get("status") or "ready"),
            "executionMode": str(workspace.get("executionMode") or "stepwise_review"),
            **summary,
        }
        previous_agent = job.get("agent") if isinstance(job.get("agent"), dict) else {}
        changed = previous_agent != next_agent
        job["agent"] = next_agent
        previous_review_previews = job.get("agentReviewPreviews") if isinstance(job.get("agentReviewPreviews"), list) else []
        if review_previews:
            job["agentReviewPreviews"] = review_previews
            changed = changed or previous_review_previews != review_previews
        elif previous_review_previews and plan_status in {
            "awaiting_confirmation", "approved", "running", "failed", "cancelled", "no_result",
        }:
            job.pop("agentReviewPreviews", None)
            changed = True
        # The first Agent message promotes the upload draft out of the empty
        # input state. Keep the draft marker for same-page legacy switching,
        # but stop presenting it as "待输入" once planning has started.
        if job.get("agentDraft") and (
            str(workspace.get("status") or "") in {"planning", "running", "awaiting_confirmation", "completed"}
            or bool(workspace.get("planningRequestId"))
            or bool(summary.get("planId"))
        ):
            job["instructionSubmitted"] = True

        if plan_status == "no_result":
            no_match = next((
                (step.get("result") or {}).get("artifact")
                for step in (plan or {}).get("steps") or []
                if isinstance(step, dict)
                and isinstance(step.get("result"), dict)
                and isinstance((step.get("result") or {}).get("artifact"), dict)
                and str(((step.get("result") or {}).get("artifact") or {}).get("kind") or "") == "no_match"
            ), {})
            job.update({
                "status": "completed", "stage": "agent_no_result",
                "progress": 1.0, "stageProgress": 1.0,
                "currentAction": "未找到可用于自动剪辑的内容",
                "detail": str(no_match.get("message") or "没有可靠候选，后续时间线与渲染步骤已跳过。"),
                "progressMode": "completed", "etaSeconds": None, "etaMode": "completed",
            })
        elif str(job.get("stage") or "") == "agent_no_result":
            # A user-authorized retry can recover a terminal no-result plan.
            # Re-enter Agent-owned state before applying the new plan status;
            # otherwise the old outer job status blocks the preview-ready
            # projection below and leaves the task card showing a stale error.
            job.update({
                "status": AWAITING_AGENT_PLAN,
                "stage": "agent_plan_running",
                "progress": max(0.0, min(.99, float(job.get("progress") or 0))),
                "stageProgress": None,
                "currentAction": "Agent 正在继续执行已确认计划",
                "detail": "已从无结果状态恢复，正在执行重试后的计划步骤。",
                "progressMode": "indeterminate", "etaSeconds": None,
                "etaMode": "unavailable",
            })

        # Discovery/search workers conventionally finish at a manual review
        # checkpoint. Autonomous plans own and immediately resolve that state,
        # so do not expose it as a user action, even for a polling interval.
        if (
            str(workspace.get("executionMode") or "") == "autonomous_review"
            and plan_status in {"approved", "running"}
            and str(job.get("status") or "") in {
                AWAITING_CONTENT_CONFIRMATION, "awaiting_confirmation",
            }
            and str(summary.get("currentStepTool") or "") in {
                "discover_people", "discover_speakers", "search_content",
                "analyze_highlights",
            }
        ):
            job.update({
                "status": AWAITING_AGENT_PLAN,
                "stage": "agent_plan_running",
                "actionRequired": None,
                "currentAction": f"Agent 正在执行：{summary.get('currentStepTitle') or '自动审核'}",
                "detail": "分析结果已交回 Agent，正在自动核定后续剪辑范围。",
                "progressMode": "indeterminate",
                "etaSeconds": None,
                "etaMode": "unavailable",
            })

        # Only the initial Agent entry is owned by plan-confirmation state.
        # Once a tool starts a media workflow, its normal queue/analysis state
        # remains authoritative and must not be overwritten here.
        agent_owned_status = str(job.get("status") or "") in {AWAITING_AGENT_PLAN, AWAITING_AGENT_INSTRUCTION}
        if agent_owned_status:
            if plan_status == "awaiting_confirmation":
                job.update({
                    "status": AWAITING_AGENT_PLAN,
                    "stage": "agent_plan_confirmation",
                    "currentAction": "请确认 Agent 执行计划",
                    "detail": "计划已生成；确认后 Agent 才会开始调用分析与剪辑工具。",
                    "progressMode": "indeterminate", "etaSeconds": None, "etaMode": "unavailable",
                })
            elif plan_status in {"approved", "running"}:
                current = str(summary.get("currentStepTitle") or "下一步")
                job.update({
                    "status": AWAITING_AGENT_PLAN,
                    "stage": "agent_plan_running",
                    "currentAction": f"Agent 正在执行：{current}",
                    "detail": f"已完成 {summary['completedSteps']}/{summary['totalSteps']} 个计划步骤",
                    "progressMode": "determinate" if summary["totalSteps"] else "indeterminate",
                    "stageCompleted": summary["completedSteps"], "stageTotal": summary["totalSteps"],
                    "stageUnit": "步骤", "etaSeconds": None, "etaMode": "unavailable",
                })
            elif plan_status == "action_required":
                current = str(summary.get("currentStepTitle") or "待确认操作")
                job.update({
                    "stage": "agent_action_required",
                    "currentAction": f"需要你确认：{current}",
                    "detail": "请在 Agent 计划面板完成此步骤所需的选择。",
                    "progressMode": "indeterminate", "etaSeconds": None, "etaMode": "unavailable",
                })
                if summary.get("currentStepAction") == "content_evidence_review":
                    job.update({"status": AWAITING_CONTENT_CONFIRMATION, "stage": "content_search_ready",
                                "actionRequired": "review_content", "currentAction": "请核验所选片段的内容与边界",
                                "detail": summary.get("currentStepMessage") or "请在候选面板预览并确认范围，再继续 Agent 计划。"})
            elif plan_status == "preview_ready":
                quality = summary.get("quality") if isinstance(summary.get("quality"), dict) else {}
                quality_status = str(quality.get("status") or "not_run")
                needs_repair = quality_status == "failed"
                job.update({
                    "status": AWAITING_AGENT_PLAN,
                    "stage": "agent_qc_failed" if needs_repair else "agent_preview_review",
                    "progress": 1.0, "stageProgress": 1.0,
                    "actionRequired": "repair_and_recheck" if needs_repair else "review_preview",
                    "currentAction": "审核样片待修正" if needs_repair else "审核样片已就绪",
                    "detail": (
                        "计划步骤已执行完毕，但质检未通过；请修正问题后重新质检。"
                        if needs_repair else
                        "计划步骤已执行完毕；请审核样片，确认后再导出高清版本。"
                    ),
                    "progressMode": "determinate", "stageCompleted": summary["completedSteps"],
                    "stageTotal": summary["totalSteps"], "stageUnit": "步骤",
                    "etaSeconds": None, "etaMode": "unavailable",
                })
            elif plan_status == "failed":
                job.update({
                    "stage": "agent_plan_failed", "currentAction": "Agent 计划执行失败",
                    "detail": "计划中有步骤未完成；请在计划面板查看原因后重试或重新规划。",
                    "progressMode": "stopped", "etaSeconds": None, "etaMode": "stopped",
                })
            elif plan_status == "cancelled":
                job.update({
                    "stage": "agent_plan_cancelled", "currentAction": "Agent 计划已停止",
                    "detail": "未完成的计划步骤已停止；你可以重新描述新的剪辑目标。",
                    "progressMode": "stopped", "etaSeconds": None, "etaMode": "stopped",
                })
            elif str(workspace.get("status") or "") == "planning" or workspace.get("planningRequestId"):
                # The model has not returned a plan yet, so there is no honest
                # denominator for a percentage.  Keep the task visibly active
                # and explain what the Agent is doing instead of presenting it
                # as a passive "waiting" state.
                planning_progress = workspace.get("planningProgress") if isinstance(workspace.get("planningProgress"), dict) else {}
                job.update({
                    "status": AWAITING_AGENT_PLAN,
                    "stage": "agent_plan_generating",
                    "currentAction": str(planning_progress.get("title") or "正在生成 Agent 执行计划"),
                    "detail": str(planning_progress.get("detail") or "正在读取可用 Skill、工具和素材范围，并拆解可确认的剪辑步骤。"),
                    "progressMode": "indeterminate", "etaSeconds": None, "etaMode": "unavailable",
                })
            elif not summary["planId"]:
                job.update({
                    "status": AWAITING_AGENT_INSTRUCTION if job.get("agentDraft") else AWAITING_AGENT_PLAN,
                    "stage": "agent_workspace_ready", "currentAction": "等待你描述剪辑目标",
                    "detail": "素材工作区已就绪，请描述你希望完成的剪辑目标。",
                })
        current_job_projection = (
            str(job.get("status") or ""), str(job.get("stage") or ""),
            str(job.get("detail") or ""), str(job.get("currentAction") or ""),
            float(job.get("progress") or 0), job.get("stageProgress"),
        )
        if (
            changed
            or current_job_projection != previous_job_projection
            or str(job.get("status") or "") in {AWAITING_AGENT_PLAN, AWAITING_AGENT_INSTRUCTION}
        ):
            job["updatedAt"] = now_iso()
            save_job(job)


def sync_agent_workspace_projection_for_job(job_id: str) -> None:
    """Refresh public Agent projection for a job being opened from storage.

    Workspace listeners update the job during live execution.  A completed job
    saved before a projection migration still needs the same sync when the user
    later opens it; otherwise review samples remain hidden in the Agent plan.
    """
    try:
        workspace = agent_platform.workspace_for_job(job_id)
        if not workspace:
            return
        plan_id = str(workspace.get("activePlanId") or "")
        plan = agent_platform.store.get("plans", plan_id) if plan_id else None
        sync_agent_workspace_to_job(workspace, plan)
    except Exception:
        logging.exception("agent_workspace_projection_sync_failed", extra={"job_id": job_id})


def execution_snapshot(job: dict[str, Any]) -> dict[str, Any]:
    """Return one canonical execution state for every API presentation.

    The legacy outer job status intentionally stays in review while automatic
    composition runs in the background.  Consumers must not have to merge
    those two state machines themselves, so this snapshot gives the nested
    operation precedence whenever it still owns a worker.
    """
    outer_status = str(job.get("status") or "")
    stage = str(job.get("stage") or "queued")
    auto = job.get("autoComposition") if isinstance(job.get("autoComposition"), dict) else {}
    auto_status = background_status(job)
    auto_active = has_background_execution(job)
    auto_phase = str(auto.get("phase") or "")
    agent = job.get("agent") if isinstance(job.get("agent"), dict) else {}
    agent_plan_status = str(agent.get("status") or "")
    agent_completed = max(0, int(agent.get("completedSteps") or 0))
    agent_total = max(0, int(agent.get("totalSteps") or 0))
    outputs = job_output_count(job)
    rejected = max(0, int(auto.get("rejectedVersionCount") or len(auto.get("rejectedVersions") or [])))
    passed = max(0, int(auto.get("qualityPassedCount") or 0))
    if "qualityPassedCount" not in auto and not auto_active:
        passed = sum(
            1 for version in job.get("outputVersions") or []
            if isinstance(version.get("qualityGate"), dict)
            and version["qualityGate"].get("passed") is True
        )

    if outer_status == CANCELLING or auto_status == "cancelling":
        status = "cancelling"
    elif outer_status in {AWAITING_AGENT_PLAN, AWAITING_AGENT_INSTRUCTION}:
        status = "running" if agent_plan_status in {"approved", "running"} else "waiting_user"
    elif auto_active:
        status = "queued" if auto_status == "queued" else "running"
    elif outer_status in {BRIEFING, QUEUED}:
        status = "queued" if outer_status == QUEUED else "running"
    elif outer_status in {RUNNING, "processing", "analyzing"}:
        status = "running"
    elif outer_status in {
        BRIEF_CONFIRMATION, AWAITING_MODEL_DECISION,
        AWAITING_CONFIRMATION, AWAITING_CONTENT_CONFIRMATION,
    }:
        status = "waiting_user"
    elif outer_status in {"completed", "failed", "cancelled"}:
        status = outer_status
    else:
        status = "failed" if job.get("error") else "waiting_user"

    if outer_status in {AWAITING_AGENT_PLAN, AWAITING_AGENT_INSTRUCTION} and agent:
        operation, phase = "agent_plan", agent_plan_status or stage
    elif auto_active or auto_status in {"completed", "partial", "failed", "cancelled"}:
        operation = (
            "quality_review"
            if auto_phase in {
                "review_vlm", "review_llm", "repair_plan", "repair_render",
                "review_compare", "evidence_recovery", "repair_replan",
            }
            else "auto_composition"
        )
        phase = auto_phase or stage
    elif stage in {"rendering", "render", "edit_planning", "alternative_planning"}:
        operation, phase = "render", stage
    elif stage.startswith("content_") or str(job.get("taskMode") or "") == "content_extract":
        durable_kind = str((job.get("analysisOperation") or {}).get("kind") or "")
        operation = {
            "person_discovery": "person_tracking",
            "speaker_discovery": "speaker_discovery",
            "target_voice_search": "target_voice_search",
            "content_initial_search": "content_search",
            "content_followup_search": "content_search",
        }.get(durable_kind) or {
            "person_edit": "person_tracking",
            "speaker_edit": "speaker_discovery",
        }.get(workflow_kind_for_job(job), "content_search")
        phase = stage
    elif status in {"queued", "running", "cancelling"}:
        operation, phase = "analysis", stage
    else:
        operation, phase = "none", stage

    if auto_status == "completed" and passed == 0 and rejected:
        outcome = "no_acceptable_output"
    elif auto_status == "partial":
        outcome = "partial_output" if outputs else "error"
    elif outputs:
        outcome = "output_ready"
    elif outer_status in {AWAITING_AGENT_PLAN, AWAITING_AGENT_INSTRUCTION} and agent_plan_status == "preview_ready":
        outcome = "ready_for_review"
    elif outer_status in {AWAITING_CONFIRMATION, AWAITING_CONTENT_CONFIRMATION}:
        outcome = "ready_for_review"
    elif outer_status == "failed":
        outcome = "error"
    elif outer_status == "cancelled":
        outcome = "cancelled"
    else:
        outcome = "none"

    facts = progress_facts_snapshot(job)
    if outer_status in {AWAITING_AGENT_PLAN, AWAITING_AGENT_INSTRUCTION} and agent:
        progress = {
            "mode": "determinate" if agent_total else "indeterminate",
            "fraction": round(min(1.0, agent_completed / agent_total), 4) if agent_total else None,
            "completed": agent_completed if agent_total else None,
            "total": agent_total if agent_total else None,
            "unit": "步骤" if agent_total else "",
        }
    elif auto_active or auto_status in {"completed", "partial", "failed", "cancelled"}:
        fraction = _finite_progress_number(auto.get("progress"))
        completed = _finite_progress_number(auto.get("completedVersions"))
        total = _finite_progress_number(auto.get("totalVersions"))
        progress = {
            "mode": "determinate" if fraction is not None else "indeterminate",
            "fraction": round(max(0.0, min(1.0, fraction)), 4) if fraction is not None else None,
            "completed": completed,
            "total": total,
            "unit": "版本" if total else "",
        }
    else:
        progress = {
            "mode": str((facts.get("stage") or {}).get("mode") or "indeterminate"),
            "fraction": (facts.get("stage") or {}).get("fraction"),
            "completed": (facts.get("stage") or {}).get("completed"),
            "total": (facts.get("stage") or {}).get("total"),
            "unit": str((facts.get("stage") or {}).get("unit") or ""),
        }

    action_required = None
    if outer_status in {AWAITING_AGENT_PLAN, AWAITING_AGENT_INSTRUCTION}:
        if agent_plan_status == "awaiting_confirmation":
            action_required = "confirm_agent_plan"
        elif agent_plan_status == "action_required":
            action_required = "resolve_agent_action"
    elif outer_status == BRIEF_CONFIRMATION:
        action_required = "confirm_brief"
    elif outer_status == AWAITING_MODEL_DECISION:
        action_required = "resolve_model_stage"
    elif not auto_active and outer_status == AWAITING_CONTENT_CONFIRMATION:
        workflow_kind = workflow_kind_for_job(job)
        if workflow_kind == "speaker_edit" and not (job.get("contentSearch") or {}).get("id"):
            discovery = job.get("voiceDiscovery") if isinstance(job.get("voiceDiscovery"), dict) else {}
            action_required = "select_speaker" if discovery.get("status") == "ready" else "start_speaker_discovery"
        elif workflow_kind == "person_edit" and not (job.get("contentSearch") or {}).get("candidates"):
            action_required = "select_person"
        else:
            action_required = "review_content"
    elif not auto_active and outer_status == AWAITING_CONFIRMATION:
        action_required = "review_highlights"

    detail = str(
        (auto.get("detail") if auto_active or outcome in {"no_acceptable_output", "partial_output"} else "")
        or job.get("currentAction") or job.get("detail") or ""
    )
    return {
        "schemaVersion": 1,
        "status": status,
        "operation": operation,
        "phase": phase,
        "active": status in {"queued", "running", "cancelling"},
        "background": bool(auto_active),
        "detail": detail,
        "outcome": outcome,
        "actionRequired": action_required,
        "progress": progress,
        "timing": facts.get("timing") or {},
        "result": {
            "outputCount": outputs,
            "qualityPassedCount": passed,
            "qualityRejectedCount": max(0, int(auto.get("qualityRejectedVariantCount") or rejected)),
            "qualityRejectedRepairCount": max(0, int(auto.get("qualityRejectedRepairCount") or 0)),
            "qualityReasons": list(dict.fromkeys(
                str(reason)
                for item in auto.get("rejectedVersions") or [] if isinstance(item, dict)
                for reason in item.get("reasons") or [] if str(reason)
            ))[:4],
            "qualityIssues": [
                {
                    key: copy.deepcopy(issue.get(key))
                    for key in (
                        "severity", "category", "description", "outputTime",
                        "segmentIds", "fixable", "duplicateCount",
                    ) if issue.get(key) is not None
                }
                for issue in (auto.get("qualityIssues") or [])[:6]
                if isinstance(issue, dict)
            ],
            "qualityRepair": copy.deepcopy(auto.get("qualityRepair"))
            if isinstance(auto.get("qualityRepair"), dict) else None,
        },
        "capabilities": {
            "canCancel": can_cancel_job(job),
            "cancelScope": "operation" if has_active_execution(job) else "job",
            "canDelete": can_delete_job(job),
        },
    }


def save_job(job: dict[str, Any]) -> None:
    _update_processing_elapsed(job)
    # Every durable mutation receives a monotonically increasing revision.
    # Lightweight polling can therefore avoid transferring and rebuilding the
    # complete review document when nothing material changed.
    job["progressFacts"] = progress_facts_snapshot(job)
    from .job_persistence import persist_job
    persist_job(job_store, job, job_path(job["id"]), atomic_write_json)


def _load_job_record(job_id: str) -> dict[str, Any] | None:
    """Load one durable job when the in-memory map is cold."""
    safe_job_id = str(job_id or "").strip()
    if not safe_job_id or Path(safe_job_id).name != safe_job_id:
        return None
    payload = job_store.get(safe_job_id)
    if payload is not None:
        normalize_job_schema(payload)
        return payload
    try:
        payload = json.loads(job_path(safe_job_id).read_text(encoding="utf-8"))
    except (OSError, TypeError, ValueError):
        payload = None
    if not isinstance(payload, dict) or str(payload.get("id") or "") != safe_job_id:
        for candidate in job_store.load_all():
            if isinstance(candidate, dict) and str(candidate.get("id") or "") == safe_job_id:
                payload = candidate
                break
    if not isinstance(payload, dict) or str(payload.get("id") or "") != safe_job_id:
        return None
    normalize_job_schema(payload)
    return payload


def ensure_job_loaded(job_id: str) -> dict[str, Any] | None:
    """Return a live job, hydrating it from durable storage if needed."""
    with jobs_lock:
        job = jobs.get(job_id)
        if job:
            return job
        restored = _load_job_record(job_id)
        if restored:
            jobs[job_id] = restored
        return restored


def _update_processing_elapsed(job: dict[str, Any], *, now: datetime | None = None) -> None:
    """Accumulate only time spent in an actively executing job state."""
    now = now or datetime.now(timezone.utc)
    accumulated = max(0.0, float(job.get("processingElapsedSeconds") or 0.0))
    active_since_raw = str(job.get("processingActiveSince") or "")
    active_since = None
    if active_since_raw:
        try:
            active_since = datetime.fromisoformat(active_since_raw.replace("Z", "+00:00"))
        except ValueError:
            active_since = None
    active = str(job.get("status") or "") in PROCESSING_ACTIVE_STATUSES or has_background_execution(job)
    if active:
        if active_since is None:
            # Legacy active jobs get a best-effort initial value from their
            # original start timestamp. Jobs with timing metadata are either
            # new or resuming after a waiting state, so they start a fresh
            # active interval now.
            if job.get("processingTimingVersion") is None and job.get("processingElapsedSeconds") is None:
                started_raw = str(job.get("startedAt") or "")
                try:
                    active_since = datetime.fromisoformat(started_raw.replace("Z", "+00:00"))
                except ValueError:
                    active_since = now
            else:
                active_since = now
        accumulated += max(0.0, (now - active_since).total_seconds())
        job["processingActiveSince"] = now.isoformat().replace("+00:00", "Z")
    else:
        if active_since is not None:
            accumulated += max(0.0, (now - active_since).total_seconds())
        job.pop("processingActiveSince", None)
    job["processingElapsedSeconds"] = round(accumulated, 3)
    job["processingTimingVersion"] = PROCESSING_TIMING_VERSION


AUTO_COMPOSITION_BATCH_SCHEMA_VERSION = 2
AUTO_VERSION_KINDS = {"independent", "repair", "formal_export"}
AUTO_QUALITY_STATUSES = {"pending", "passed", "needs_review", "review_unavailable"}


def output_version_kind(version: dict[str, Any]) -> str:
    explicit = str(version.get("variantKind") or "")
    if explicit in AUTO_VERSION_KINDS:
        return explicit
    if str(version.get("strategyKey") or "") == "review_repair":
        return "repair"
    if version.get("previewOnly"):
        return "independent"
    return "formal_export"


def output_version_quality_status(version: dict[str, Any]) -> str:
    explicit = str(version.get("qualityStatus") or "")
    if explicit in AUTO_QUALITY_STATUSES:
        return explicit
    gate = version.get("qualityGate") if isinstance(version.get("qualityGate"), dict) else {}
    review_status = str(version.get("reviewStatus") or "")
    if gate.get("passed") is True:
        return "passed"
    if review_status in {"degraded", "interrupted_needs_user_review", "review_unavailable"}:
        return "review_unavailable"
    if gate.get("passed") is False or version.get("manualReviewRequired"):
        return "needs_review"
    return "pending"


def _refresh_auto_composition_batches(job: dict[str, Any]) -> bool:
    """Normalize additive batch metadata without changing legacy version IDs."""
    auto = job.get("autoComposition") if isinstance(job.get("autoComposition"), dict) else None
    versions = job.get("outputVersions") if isinstance(job.get("outputVersions"), list) else []
    changed = False
    automatic_strategy_keys = {
        "vlm", "narrative", "emotion", "information", "event_alternative", "review_repair",
    }
    # A short-lived migration tagged every ordinary formal output as an auto
    # composition. Undo only that unambiguous legacy marker; true auto exports
    # retain either their source version or an automatic strategy key.
    for version in versions:
        if (
            str(version.get("generationBatchId") or "") == "batch_formal_legacy"
            and not version.get("sourceVersionId") and not version.get("parentVersionId")
            and str(version.get("strategyKey") or "") not in automatic_strategy_keys
            and not version.get("previewOnly")
        ):
            version.pop("generationBatchId", None)
            version.pop("variantKind", None)
            version.pop("qualityStatus", None)
            changed = True
    automatic_ids = {
        str(version.get("id") or "")
        for version in versions
        if version.get("previewOnly")
        or str(version.get("strategyKey") or "") in automatic_strategy_keys
        or bool(version.get("generationBatchId"))
    }
    automatic_versions = [
        version for version in versions
        if str(version.get("id") or "") in automatic_ids
        or str(version.get("sourceVersionId") or version.get("parentVersionId") or "") in automatic_ids
    ]
    if auto is None and not automatic_versions:
        return changed
    if auto is None:
        auto = {}
        job["autoComposition"] = auto
    batches = auto.get("batches")
    if not isinstance(batches, list):
        batches = []
        auto["batches"] = batches
        changed = True
    batch_lookup = {str(batch.get("id") or ""): batch for batch in batches if isinstance(batch, dict)}
    legacy_batch_id = f"batch_legacy_{str(job.get('id') or 'job')[-12:]}"
    legacy_members: list[str] = []
    version_lookup = {str(version.get("id") or ""): version for version in versions}
    automatic_version_ids = {str(version.get("id") or "") for version in automatic_versions}
    for version in versions:
        if str(version.get("id") or "") not in automatic_version_ids:
            continue
        kind = output_version_kind(version)
        quality_status = output_version_quality_status(version)
        if version.get("variantKind") != kind:
            version["variantKind"] = kind
            changed = True
        if version.get("qualityStatus") != quality_status:
            version["qualityStatus"] = quality_status
            changed = True
        batch_id = str(version.get("generationBatchId") or "")
        if not batch_id and kind in {"independent", "repair"}:
            version["generationBatchId"] = legacy_batch_id
            batch_id = legacy_batch_id
            changed = True
        elif not batch_id and kind == "formal_export":
            parent = version_lookup.get(str(version.get("sourceVersionId") or version.get("parentVersionId") or ""))
            parent_batch = str((parent or {}).get("generationBatchId") or "")
            version["generationBatchId"] = parent_batch or "batch_formal_legacy"
            batch_id = str(version["generationBatchId"])
            changed = True
        if batch_id == legacy_batch_id:
            legacy_members.append(str(version.get("id") or ""))
    if legacy_members and legacy_batch_id not in batch_lookup:
        requested = max(1, min(4, int(
            auto.get("plannedVariantCount")
            or (job.get("request") or {}).get("autoVariantCount")
            or len([version_id for version_id in legacy_members if output_version_kind(version_lookup.get(version_id, {})) == "independent"])
            or 1
        )))
        batch = {
            "schemaVersion": AUTO_COMPOSITION_BATCH_SCHEMA_VERSION,
            "id": legacy_batch_id,
            "mode": "legacy",
            "status": "completed",
            "targetVariantCount": requested,
            "requestedAdditionalCount": requested,
            "createdAt": str(job.get("createdAt") or now_iso()),
            "completedAt": str(job.get("updatedAt") or now_iso()),
            "versionIds": legacy_members,
        }
        batches.append(batch)
        batch_lookup[legacy_batch_id] = batch
        changed = True
    for batch in batches:
        if not isinstance(batch, dict) or not batch.get("id"):
            continue
        batch_id = str(batch["id"])
        members = [version for version in versions if str(version.get("generationBatchId") or "") == batch_id]
        independent = [version for version in members if output_version_kind(version) == "independent"]
        repairs = [version for version in members if output_version_kind(version) == "repair"]
        counts = {
            "versionIds": [str(version.get("id") or "") for version in members],
            "independentVersionIds": [str(version.get("id") or "") for version in independent],
            "repairVersionIds": [str(version.get("id") or "") for version in repairs],
            "generatedVariantCount": len(independent),
            "repairVersionCount": len(repairs),
            "qualityPassedCount": sum(output_version_quality_status(version) == "passed" for version in members),
            "qualityNeedsReviewCount": sum(output_version_quality_status(version) == "needs_review" for version in members),
            "qualityReviewUnavailableCount": sum(output_version_quality_status(version) == "review_unavailable" for version in members),
        }
        target = max(1, min(4, int(batch.get("targetVariantCount") or counts["generatedVariantCount"] or 1)))
        counts["missingVariantCount"] = max(0, target - counts["generatedVariantCount"])
        for key, value in counts.items():
            if batch.get(key) != value:
                batch[key] = value
                changed = True
        if batch.get("schemaVersion") != AUTO_COMPOSITION_BATCH_SCHEMA_VERSION:
            batch["schemaVersion"] = AUTO_COMPOSITION_BATCH_SCHEMA_VERSION
            changed = True
    if batches and not auto.get("currentBatchId"):
        auto["currentBatchId"] = str(batches[-1].get("id") or "")
        changed = True
    return changed


def _new_auto_composition_batch(
    job: dict[str, Any], *, target_variant_count: int, requested_additional_count: int,
    mode: str, target_seconds: float | None = None, evidence_source: str = "",
) -> dict[str, Any]:
    auto = job.setdefault("autoComposition", {})
    batches = auto.setdefault("batches", [])
    batch = {
        "schemaVersion": AUTO_COMPOSITION_BATCH_SCHEMA_VERSION,
        "id": f"batch_{uuid.uuid4().hex[:12]}",
        "mode": mode,
        "status": "running",
        "targetVariantCount": max(1, min(4, int(target_variant_count))),
        "requestedAdditionalCount": max(1, min(4, int(requested_additional_count))),
        "createdAt": now_iso(),
        "versionIds": [],
        "independentVersionIds": [],
        "repairVersionIds": [],
    }
    if target_seconds is not None:
        batch["targetSeconds"] = round(float(target_seconds), 3)
    if evidence_source:
        batch["evidenceSource"] = str(evidence_source)
    batches.append(batch)
    auto["currentBatchId"] = batch["id"]
    return batch


def normalize_output_versions(job: dict[str, Any]) -> bool:
    """Upgrade legacy single-output-state jobs to an append-only version list."""
    changed = False
    versions = job.get("outputVersions")
    if not isinstance(versions, list):
        versions = []
        job["outputVersions"] = versions
        changed = True
    if not versions and job.get("outputs"):
        created_at = str(job.get("updatedAt") or job.get("createdAt") or now_iso())
        legacy_outputs = job["outputs"]
        for item in legacy_outputs:
            item.setdefault("versionId", "v001")
            item.setdefault("versionNumber", 1)
            item.setdefault("versionCreatedAt", created_at)
        versions.append({
            "id": "v001",
            "number": 1,
            "createdAt": created_at,
            "outputMode": str(job.get("outputMode") or ("single_reel" if len(legacy_outputs) == 1 else "separate_events")),
            "confirmedGroupIds": list(job.get("confirmedGroupIds", [])),
            "confirmedIndices": list(job.get("confirmedIndices", [])),
            "outputs": legacy_outputs,
        })
        job["currentOutputVersionId"] = "v001"
        changed = True
    if versions:
        current_id = str(job.get("currentOutputVersionId") or versions[-1].get("id"))
        current = next((version for version in versions if str(version.get("id")) == current_id), versions[-1])
        if job.get("currentOutputVersionId") != current.get("id"):
            job["currentOutputVersionId"] = current.get("id")
            changed = True
        # Keep the legacy field as a pointer to the active version for the rest of the app.
        if job.get("outputs") is not current.get("outputs"):
            job["outputs"] = current.setdefault("outputs", [])
            changed = True
    if _refresh_auto_composition_batches(job):
        changed = True
    return changed


def next_output_version(job: dict[str, Any]) -> tuple[str, int]:
    normalize_output_versions(job)
    numbers = [int(version.get("number") or 0) for version in job.get("outputVersions", [])]
    number = max([*numbers, int(job.get("reservedOutputVersionNumber") or 0)]) + 1
    return f"v{number:03d}", number


def find_output_version(job: dict[str, Any], version_id: str) -> dict[str, Any] | None:
    normalize_output_versions(job)
    return next((version for version in job.get("outputVersions", []) if str(version.get("id")) == version_id), None)


def all_job_outputs(job: dict[str, Any]) -> list[dict[str, Any]]:
    normalize_output_versions(job)
    version_outputs = [
        item
        for version in job.get("outputVersions", [])
        for collection in (version.get("outputs", []), version.get("previewOutputs", []))
        for item in collection
    ]
    return version_outputs + [
        item for item in [
            *(job.get("agentReviewPreviews", []) or []),
            *(job.get("agentPreviewOutputs", []) or []),
        ]
        if isinstance(item, dict)
    ]


def job_has_visible_review_result(job: dict[str, Any]) -> bool:
    return bool(
        job_output_count(job)
        or job.get("agentReviewPreviews")
        or job.get("agentPreviewOutputs")
    )


def output_download_context(job: dict[str, Any], filename: str) -> tuple[dict[str, Any], dict[str, Any], int] | None:
    """Find an output together with its version metadata and 1-based position."""
    normalize_output_versions(job)
    for version in job.get("outputVersions", []):
        for collection in (version.get("outputs", []), version.get("previewOutputs", [])):
            for position, item in enumerate(collection, 1):
                if str(item.get("filename")) == str(filename):
                    return item, version, position
    for position, item in enumerate([
        *(job.get("agentReviewPreviews", []) or []),
        *(job.get("agentPreviewOutputs", []) or []),
    ], 1):
        if isinstance(item, dict) and str(item.get("filename")) == str(filename):
            return item, {
                "id": "agent-review-previews", "number": 0,
                "displayName": "Agent 审核预览", "previewOnly": True,
            }, position
    return None


def _hydrate_legacy_quality_diagnostics(job: dict[str, Any]) -> bool:
    """Recover concrete QC findings for jobs saved before public diagnostics."""
    auto = job.get("autoComposition") if isinstance(job.get("autoComposition"), dict) else None
    diagnostics_version = "quality-diagnostics-tiered-display-v3"
    if not auto or not auto.get("rejectedVersions") or auto.get("qualityDiagnosticsVersion") == diagnostics_version:
        return False
    work_directory = str(job.get("workDirectory") or "").strip()
    review_directory = Path(work_directory) / "composition-reviews" if work_directory else None
    if not review_directory or not review_directory.is_dir():
        return False
    reports: list[dict[str, Any]] = []
    for path in review_directory.glob("cache-*.json"):
        try:
            report = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError, TypeError):
            continue
        if isinstance(report, dict) and report.get("status") == "completed":
            reports.append(report)
    if not reports:
        return False
    selected_issues: list[list[dict[str, Any]]] = []
    for rejected in auto.get("rejectedVersions") or []:
        if not isinstance(rejected, dict):
            continue
        score = float(rejected.get("score") or 0)
        closest = min(reports, key=lambda report: abs(float(report.get("overallScore") or 0) - score))
        calibrated = closest
        if str(closest.get("calibrationVersion") or "") != REVIEW_CALIBRATION_VERSION:
            raw = copy.deepcopy(closest)
            raw["overallScore"] = float(closest.get("modelOverallScore") or closest.get("overallScore") or 0)
            rendered_audio_issues = [
                item for item in closest.get("deterministicChecks") or []
                if isinstance(item, dict) and item.get("source") == "rendered_audio"
            ]
            target = job.get("totalTargetSeconds") or (job.get("request") or {}).get("totalTargetSeconds")
            actual = (closest.get("evidence") or {}).get("duration")
            raw = sanitize_review_report(
                raw,
                timeline={"duration": float(actual or 0), "segments": []},
                target_seconds=float(target) if target not in (None, "", "auto") else None,
            )
            calibrated = calibrate_review_report(
                raw, media_evidence={"audioMetrics": {"issues": rendered_audio_issues}, "visualMetrics": {}},
                target_seconds=float(target) if target not in (None, "", "auto") else None,
                actual_seconds=float(actual) if actual not in (None, "") else None,
            )
        rejected["score"] = calibrated.get("overallScore")
        refreshed_reasons = [
            str(reason) for reason in rejected.get("reasons") or []
            if not re.search(r"校准审片得分|低于展示门槛|仍有\s*\d+\s*个关键问题", str(reason))
        ]
        critical_count = int(calibrated.get("criticalCount") or 0)
        current_score = float(calibrated.get("overallScore") or 0)
        if critical_count:
            refreshed_reasons.append(f"按当前规则仍有 {critical_count} 个关键问题")
        if current_score < PASS_SCORE:
            refreshed_reasons.append(
                f"历史审片按当前策略重新校准为 {current_score:.1f} 分，低于展示门槛 {PASS_SCORE:.0f}"
            )
        rejected["reasons"] = list(dict.fromkeys(refreshed_reasons))[:4]
        rejected["qualityPolicyVersion"] = QUALITY_GATE_VERSION
        rejected["legacyRecalibrated"] = True
        deterministic = [] if "root-cause" in str(calibrated.get("calibrationVersion") or "") else calibrated.get("deterministicChecks") or []
        rejected["issues"] = deduplicate_issues(calibrated.get("issues") or [], deterministic)[:8]
        selected_issues.append(rejected["issues"])
        rejected["summary"] = str(closest.get("summary") or "")[:500]
    auto["qualityIssues"] = deduplicate_issues(*selected_issues)[:8]
    auto["qualityDiagnosticsVersion"] = diagnostics_version
    return True


def _prepare_recoverable_render_job(job: dict[str, Any]) -> None:
    """Put a persisted render task into a state its worker can actually resume."""
    auto = job.get("autoComposition") if isinstance(job.get("autoComposition"), dict) else None
    if auto and str(auto.get("status") or "") in {"queued", "running"}:
        # Background automatic previews deliberately keep the parent job in
        # review. Moving the outer state to `queued` makes the recovered worker
        # return immediately because run_automatic_composition only accepts
        # awaiting_confirmation.
        job.update({
            "status": AWAITING_CONFIRMATION,
            "stage": "auto_composition",
            "detail": "事件审核已就绪；服务正在恢复自动成片",
            "currentAction": "服务正在恢复自动成片",
            "etaSeconds": None,
            "etaMode": "collecting",
            "progressMode": "background",
            "updatedAt": now_iso(),
        })
        auto.update({
            "status": "queued",
            "detail": "服务重启后正在恢复自动成片",
            "recovering": True,
        })
        auto.pop("cancelled", None)
        auto.pop("error", None)
        return
    job.update({
        "status": QUEUED,
        "stage": "queued",
        "detail": "服务重启后正在恢复未完成的渲染任务",
        "currentAction": "渲染任务已重新进入持久化队列",
        "etaSeconds": None,
        "etaMode": "collecting",
        "progressMode": "indeterminate",
        "updatedAt": now_iso(),
    })


def _retain_interrupted_auto_previews(job: dict[str, Any]) -> bool:
    """Expose unreviewed previews as clearly labelled manual drafts."""
    retained_ids: list[str] = []
    for version in job.get("outputVersions") or []:
        if not version.get("previewOnly") or not version.get("outputs"):
            continue
        gate = version.get("qualityGate") if isinstance(version.get("qualityGate"), dict) else {}
        if gate.get("passed") is True:
            continue
        fallback_gate = {
            "schemaVersion": 1,
            "qualityGateVersion": QUALITY_GATE_VERSION,
            "passed": False,
            "recommended": False,
            "score": float(gate.get("score") or 0),
            "passThreshold": PASS_SCORE,
            "criticalCount": int(gate.get("criticalCount") or 0),
            "majorCount": int(gate.get("majorCount") or 0),
            "reasons": ["服务重启中断了自动审片，当前版本仅供人工复核"],
            "issues": list(gate.get("issues") or []),
        }
        version.update({
            "manualReviewRequired": True,
            "reviewStatus": "interrupted_needs_user_review",
            "recommended": False,
            "recommendationReason": "自动审片被服务重启中断，仅保留为人工复核草稿",
            "qualityGate": fallback_gate,
        })
        for output in version.get("outputs") or []:
            output.update({
                "manualReviewRequired": True,
                "reviewStatus": "interrupted_needs_user_review",
                "qualityGate": fallback_gate,
            })
        retained_ids.append(str(version.get("id") or ""))
    if not retained_ids:
        return False
    auto = job.setdefault("autoComposition", {})
    auto.update({
        "manualReviewRequired": True,
        "manualReviewVersionId": retained_ids[-1],
        "qualityPassedCount": 0,
        "hasOutputs": True,
    })
    selected = next(
        (version for version in job.get("outputVersions") or [] if str(version.get("id") or "") == retained_ids[-1]),
        None,
    )
    job["currentOutputVersionId"] = selected.get("id") if selected else None
    job["outputs"] = list(selected.get("outputs") or []) if selected else []
    _sync_output_manifest(job)
    return True


def _persisted_output_count(job: dict[str, Any]) -> int:
    versions = job.get("outputVersions") if isinstance(job.get("outputVersions"), list) else []
    if versions:
        return sum(
            len(version.get("outputs") or [])
            for version in versions if isinstance(version, dict)
        )
    return len(job.get("outputs") or [])


def _normalize_loaded_workflow_transients(
    job: dict[str, Any], *, recoverable_analysis: bool,
) -> bool:
    """Repair stale nested progress without deleting reusable results."""
    changed = False
    workflow = str(job.get("workflowKind") or (job.get("request") or {}).get("workflowKind") or "")
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    outer_status = str(job.get("status") or "")
    active_nested = {"queued", "indexing", "scanning", "running"}
    current = job.get("contentSearch") if isinstance(job.get("contentSearch"), dict) else None
    pending = job.get("pendingContentSearch") if isinstance(job.get("pendingContentSearch"), dict) else None
    no_person_target = not bool(
        request.get("contentSearchTargetPersonId")
        or (request.get("contentSearchPersonTarget") or {}).get("personIds")
    )
    if (
        workflow == "person_edit" and no_person_target and current
        and str(current.get("status") or "") in active_nested
    ):
        interrupted = copy.deepcopy(current)
        interrupted.update({"status": "interrupted", "updatedAt": now_iso()})
        history = job.setdefault("contentSearchHistory", [])
        if interrupted.get("id") and not any(
            str(item.get("id") or "") == str(interrupted.get("id") or "")
            for item in history if isinstance(item, dict)
        ):
            history.append(interrupted)
        job["contentSearch"] = None
        current = None
        changed = True
    if not recoverable_analysis and outer_status not in {"running", "cancelling"}:
        for nested in (current, pending):
            if nested and str(nested.get("status") or "") in active_nested:
                nested.update({"status": "interrupted", "updatedAt": now_iso()})
                changed = True
        discovery = job.get("voiceDiscovery") if isinstance(job.get("voiceDiscovery"), dict) else None
        if discovery and str(discovery.get("status") or "") == "running":
            discovery.update({
                "status": "failed", "error": "服务重启中断了说话人识别",
                "completedAt": now_iso(),
            })
            changed = True
    operation = job.get("analysisOperation") if isinstance(job.get("analysisOperation"), dict) else {}
    operation_kind = str(operation.get("kind") or "")
    compatible = {
        "highlight": {"brief_generation", "highlight_analysis"},
        "content_search": {"content_initial_search", "content_followup_search", "target_voice_search"},
        "person_edit": {"person_discovery", "content_initial_search", "content_followup_search"},
        "speaker_edit": {"speaker_discovery", "target_voice_search"},
    }.get(workflow, set())
    if operation_kind not in compatible:
        if workflow == "speaker_edit":
            kind = "speaker_discovery"
        elif workflow == "person_edit":
            kind = "content_followup_search" if pending else "content_initial_search" if not no_person_target else "person_discovery"
        elif workflow == "content_search":
            kind = "target_voice_search" if pending and pending.get("kind") == "voice_identity" else "content_followup_search" if pending else "content_initial_search"
        else:
            kind = "brief_generation" if job.get("briefStatus") == "pending" else "highlight_analysis"
        payload: dict[str, Any] = {}
        if kind == "target_voice_search" and pending:
            payload = {"profileId": str(pending.get("profileId") or ""), "query": str(pending.get("query") or "")}
        job["analysisOperation"] = {
            "schemaVersion": 1, "kind": kind, "payload": payload,
            "status": "queued" if recoverable_analysis else "interrupted",
            "attempt": max(0, int(operation.get("attempt") or 0)),
            "migratedAt": now_iso(),
        }
        changed = True
    return changed


def load_jobs() -> None:
    recoverable_analysis_job_ids = analysis_task_store.recoverable_job_ids()
    recoverable_render_job_ids = render_task_store.recoverable_job_ids()
    records = {job["id"]: job for job in job_store.load_all() if isinstance(job, dict) and job.get("id")}
    for path in (settings.data_root / "jobs").glob("*.json"):
        try:
            file_job = json.loads(path.read_text(encoding="utf-8"))
            stored = records.get(file_job.get("id"))
            if not stored:
                records[file_job["id"]] = file_job
        except (OSError, ValueError, KeyError):
            continue
    for job in records.values():
        try:
            changed = normalize_job_schema(job)
            job_id = str(job.get("id") or "")
            if _normalize_loaded_workflow_transients(
                job, recoverable_analysis=job_id in recoverable_analysis_job_ids,
            ):
                changed = True
            artifact_health = recovery_artifact_health(job)
            if job.get("artifactHealth") != artifact_health:
                job["artifactHealth"] = artifact_health
                changed = True
            if has_active_execution(job) and not artifact_health["sourcePresent"]:
                analysis_task_store.cancel_job(job_id)
                render_task_store.cancel_job(job_id)
                job.update({
                    "status": "failed", "stage": "failed", "failureCode": "source_missing",
                    "detail": "服务恢复失败：源视频文件不存在",
                    "currentAction": "请重新上传源视频", "progressMode": "stopped",
                    "etaSeconds": None, "etaMode": "stopped", "updatedAt": now_iso(),
                })
                changed = True
            elif has_active_execution(job) and job_id in recoverable_analysis_job_ids:
                checkpoint_available = load_analysis_checkpoint(Path(job.get("workDirectory") or "")) is not None
                job.update({
                    "status": "queued",
                    "stage": "queued",
                    "detail": "服务重启后正在恢复未完成的分析任务",
                    "currentAction": "任务已重新进入持久化队列",
                    "etaSeconds": None,
                    "etaMode": "collecting",
                    "progressMode": "indeterminate",
                    "resumeAvailable": checkpoint_available,
                    "updatedAt": now_iso(),
                })
                changed = True
            elif job_id in recoverable_render_job_ids:
                # Automatic previews deliberately keep the main job in the
                # review state. Final exports use an active execution state and
                # are moved back to queued while their persisted render task is
                # recovered by startup_maintenance().
                _prepare_recoverable_render_job(job)
                changed = True
            elif (
                str(job.get("status") or "") == CANCELLING
                and not has_background_execution(job)
                and job_id not in recoverable_analysis_job_ids
                and job_id not in recoverable_render_job_ids
            ):
                # The cancellation request is persisted before the worker is
                # allowed to continue. If the service restarts while a native
                # or OCR call is blocking, no worker remains to finish it.
                now = now_iso()
                job.update({
                    "status": "cancelled", "stage": "cancelled",
                    "detail": "任务已取消", "currentAction": "任务已取消",
                    "etaSeconds": None, "etaMode": "stopped",
                    "progressMode": "stopped", "pendingDecision": None,
                    "updatedAt": now,
                })
                changed = True
            elif has_background_execution(job):
                # No durable render task remains, so the background worker
                # cannot resume. Keep the completed analysis available for
                # review instead of failing the whole job.
                auto_state = job.get("autoComposition") if isinstance(job.get("autoComposition"), dict) else {}
                has_outputs = bool(_persisted_output_count(job))
                auto_state.update({
                    "status": "partial" if has_outputs else "failed",
                    "phase": "done",
                    "hasOutputs": has_outputs,
                    "error": "服务重启导致后台自动成片中断",
                    "detail": (
                        "服务重启中断了自动成片，已生成版本仍可预览"
                        if has_outputs else "服务重启中断了自动成片，分析候选仍可审核"
                    ),
                })
                if has_outputs:
                    _retain_interrupted_auto_previews(job)
                job.update({
                    "status": AWAITING_CONFIRMATION,
                    "stage": "review",
                    "detail": auto_state["detail"],
                    "currentAction": "请继续审核候选或重新生成",
                    "etaSeconds": None,
                    "etaMode": "stopped",
                    "progressMode": "completed",
                    "updatedAt": now_iso(),
                })
                changed = True
            elif (
                str(job.get("status") or "") in {QUEUED, AWAITING_CONFIRMATION}
                and isinstance(job.get("autoComposition"), dict)
                and str(job["autoComposition"].get("status") or "") == "partial"
                and bool(_persisted_output_count(job))
                and any(
                    version.get("previewOnly")
                    and not version.get("manualReviewRequired")
                    and not (
                        isinstance(version.get("qualityGate"), dict)
                        and version["qualityGate"].get("passed") is True
                    )
                    for version in job.get("outputVersions") or []
                )
            ):
                # Repair jobs left permanently queued by the previous render
                # recovery implementation after its queue record had already
                # reached a terminal state.
                _retain_interrupted_auto_previews(job)
                job.update({
                    "status": AWAITING_CONFIRMATION,
                    "stage": "review",
                    "detail": "服务重启中断了自动成片，已生成版本可人工复核",
                    "currentAction": "请复核已保留样片或重新生成",
                    "etaSeconds": None,
                    "etaMode": "stopped",
                    "progressMode": "completed",
                    "updatedAt": now_iso(),
                })
                changed = True
            elif has_active_execution(job):
                checkpoint_available = load_analysis_checkpoint(Path(job.get("workDirectory") or "")) is not None
                interrupted_at = now_iso()
                job.update(interrupted_job_patch(
                    checkpoint_available=checkpoint_available,
                    now=interrupted_at,
                ))
                changed = True
            # Content extraction used the highlight review state before the
            # dedicated content-review workflow existed.  Leaving those jobs
            # in awaiting_confirmation makes the current UI render event
            # controls and also causes the content confirmation endpoint to
            # reject an otherwise valid re-edit.  Migrate only jobs that were
            # explicitly returned to content editing; ordinary completed
            # outputs remain completed.
            if (
                str(job.get("taskMode") or "") == "content_extract"
                and job.get("status") == "awaiting_confirmation"
                and bool(job.get("reediting"))
                and isinstance(job.get("contentSearch"), dict)
            ):
                job["status"] = "awaiting_content_confirmation"
                job["stage"] = "content_confirmation"
                job["detail"] = "已返回内容片段确认，可重新选择检索结果后生成新版本；不会重新分析视频"
                job["currentAction"] = "等待重新确认内容片段"
                job["updatedAt"] = now_iso()
                changed = True
            if "messages" not in job:
                count = len(job.get("outputs", []))
                job["messages"] = [
                    {
                        "id": f"msg_{uuid.uuid4().hex}",
                        "role": "user",
                        "text": f"历史任务：分析 {job.get('filename', '视频')} 的视觉高光",
                        "kind": "request",
                        "createdAt": job.get("createdAt", now_iso()),
                    },
                    {
                        "id": f"msg_{uuid.uuid4().hex}",
                        "role": "assistant",
                        "text": f"该任务已生成 {count} 条高光，可以继续播放、下载或换掉某一条。",
                        "kind": "result",
                        "createdAt": job.get("updatedAt", now_iso()),
                    },
                ]
                changed = True
            if "parentJobId" not in job:
                job["parentJobId"] = None
                changed = True
            if "storageMode" not in job:
                job["storageMode"] = "editable"
                changed = True
            if "excludedRanges" not in job:
                job["excludedRanges"] = []
                changed = True
            if "reviewExcludedCandidates" not in job:
                job["reviewExcludedCandidates"] = []
                changed = True
            # Existing tasks keep their previous manual-review behavior; only
            # newly created tasks opt into automatic multi-version composition.
            if "autoCompose" not in job:
                job["autoCompose"] = False
                changed = True
            manual_index = 0
            for group in job.get("eventGroups", []):
                if group.get("assemblyStrategy") != "manual":
                    continue
                manual_index += 1
                if str(group.get("title") or "").strip() in {"时间轴选区高光", "手动事件高光", "时间轴片段", "时间轴选区"}:
                    group["title"] = f"手动高光片段 {manual_index:02d}"
                    changed = True
            if job.get("status") == "awaiting_confirmation" and not job.get("pendingSelectionGroupIds"):
                latest_message = (job.get("messages") or [])[-1] if job.get("messages") else {}
                latest_notice = latest_message if latest_message.get("role") == "assistant" and re.search(r"已准备好你选中的多个时间轴片段|已找到相同的时间轴选区", str(latest_message.get("text") or "")) else None
                manual_groups = [group for group in job.get("eventGroups", []) if group.get("assemblyStrategy") == "manual"]
                if latest_notice and manual_groups:
                    job["pendingSelectionGroupIds"] = [str(manual_groups[-1].get("id"))]
                    changed = True
            if normalize_output_versions(job):
                changed = True
            if _hydrate_legacy_quality_diagnostics(job):
                changed = True
            save_job(job)
            jobs[job["id"]] = job
        except (OSError, ValueError, KeyError, TypeError):
            continue


def _dedupe_content_text(value: Any, *, limit: int = 600) -> str:
    """Remove repeated VLM clauses without rewriting their meaning."""
    text = re.sub(r"\s+", " ", str(value or "").strip())
    if not text:
        return ""
    parts = [part.strip() for part in re.split(r"(?<=[。！？；;])", text) if part.strip()]
    unique: list[str] = []
    seen: set[str] = set()
    for part in parts:
        key = re.sub(r"[\s。！？；;，,]+", "", part).casefold()
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(part)
    return "".join(unique)[:limit] or text[:limit]


def _content_public_detail(job: dict[str, Any]) -> str:
    detail = str(job.get("detail") or "")
    outputs = job.get("outputs") if isinstance(job.get("outputs"), list) else []
    if "事件审核" in detail:
        return "已返回内容片段确认，可重新选择检索结果后生成新版本；不会重新分析视频"
    if re.search(r"高光成片|高光事件|精彩镜头", detail):
        segment_count = sum(int(item.get("segmentCount") or 0) for item in outputs if isinstance(item, dict))
        return (
            f"已将 {segment_count} 个已确认内容片段合成为 {len(outputs)} 条视频"
            if outputs else "内容视频已生成"
        )
    return detail


def content_search_coverage_snapshot(search: Any) -> dict[str, Any] | None:
    if not isinstance(search, dict) or not search.get("id"):
        return None
    completeness = search.get("completeness") if isinstance(search.get("completeness"), dict) else {}
    stats = search.get("retrievalStats") if isinstance(search.get("retrievalStats"), dict) else {}
    complete = bool(search.get("coverageComplete")) or str(completeness.get("status") or "") == "complete"
    semantic_total = max(0, int(
        completeness.get("evaluatedUnitCount")
        or stats.get("rerankUnitCount")
        or stats.get("unitTotal")
        or 0
    ))
    semantic_completed = max(0, min(
        semantic_total,
        int(stats.get("semanticVerifiedUnitCount") or stats.get("rerankUnitCount") or 0),
    ))
    channels = [copy.deepcopy(item) for item in completeness.get("channels") or [] if isinstance(item, dict)]
    semantic_percent = round(min(100.0, semantic_completed / semantic_total * 100), 1) if semantic_total else None
    return {
        "schemaVersion": 2,
        "requiredComplete": complete,
        "state": "complete" if complete else "partial",
        "semantic": {
            "completed": semantic_completed, "total": semantic_total,
            "percent": semantic_percent,
        },
        "operations": channels,
        # Deliberately omit an overall percentage for partial coverage. A
        # semantic 100% does not mean every required visual/audio operator ran.
        "overallPercent": 100.0 if complete else None,
    }


def content_search_session_snapshot(job: dict[str, Any]) -> dict[str, Any] | None:
    """Expose one authoritative content-search lifecycle to every client."""
    if str(job.get("taskMode") or "") != "content_extract":
        return None
    usable = job.get("contentSearch") if isinstance(job.get("contentSearch"), dict) else {}
    pending = job.get("pendingContentSearch") if isinstance(job.get("pendingContentSearch"), dict) else {}
    active = pending if pending.get("id") else usable
    state = (
        "running" if pending.get("id") and str(pending.get("status") or "") in {"queued", "indexing", "scanning", "running"}
        else "action_required" if active.get("clarification")
        else "ready" if active.get("id")
        else "empty"
    )
    return {
        "schemaVersion": 1,
        "activeSearchId": str(active.get("id") or ""),
        "usableSearchId": str(usable.get("id") or ""),
        "previousUsableSearchId": str(usable.get("id") or "") if pending.get("id") else "",
        "state": state,
    }


def content_workflow_snapshot(job: dict[str, Any]) -> dict[str, Any] | None:
    """Canonical content workflow consumed by every presentation surface."""
    if str(job.get("taskMode") or "") != "content_extract":
        return None
    workflow_kind = workflow_kind_for_job(job)
    status = str(job.get("status") or "")
    stage = str(job.get("stage") or "")
    pending = job.get("pendingContentSearch") if isinstance(job.get("pendingContentSearch"), dict) else {}
    search = pending if pending.get("id") else (
        job.get("contentSearch") if isinstance(job.get("contentSearch"), dict) else {}
    )
    execution = search.get("executionPlan") if isinstance(search.get("executionPlan"), dict) else {}
    allowed = [str(value) for value in execution.get("allowedCapabilities") or (job.get("request") or {}).get("contentAllowedCapabilities") or []]
    recognition = job.get("recognition") if isinstance(job.get("recognition"), dict) else {}
    processed = {
        str(value) for value in (
            recognition.get("processedModalities")
            or execution.get("executedCapabilities") or []
        )
    }
    labels = {
        "speech": "识别对白", "person": "识别人物并关联轨迹", "visual": "建立画面索引",
        "ocr": "识别屏幕文字", "audio": "识别声音",
    }
    phase = "prepare"
    state = "running" if status in {"queued", "running", "cancelling"} else "ready"
    if status in {"failed", "cancelled"}:
        state = "failed"
    if status == "completed":
        phase, state = "complete", "ready"
    elif stage in {"rendering", "render", "auto_composition"}:
        phase = "render"
    elif status == "awaiting_content_confirmation" or stage in {"content_search_ready", "content_confirmation"}:
        phase = "review"
    elif stage not in {"queued", "starting", "probing"}:
        phase = "search"

    clarification = search.get("clarification") if isinstance(search.get("clarification"), dict) else None
    coverage_status = str(search.get("coverageStatus") or "")
    warnings = [str(value) for value in execution.get("warnings") or [] if str(value)]
    action_required = None
    if clarification:
        state = "action_required"
        action_required = {
            "kind": str(clarification.get("kind") or "query_detail"),
            "title": str(clarification.get("question") or "需要确认下一步"),
            "message": str(clarification.get("message") or "请确认后继续。"),
            "blocking": True,
        }
    elif coverage_status in {"partial", "unavailable"} or warnings:
        state = "action_required" if not search.get("candidates") else "ready"
        action_required = {
            "kind": "coverage_incomplete",
            "title": "部分分析未完成",
            "message": warnings[0] if warnings else "必要分析没有覆盖完整检索范围。",
            "blocking": not bool(search.get("candidates")),
        }

    workflow_terms = {
        "content_search": ("检索目标内容", "确认内容片段", "生成内容视频"),
        "person_edit": ("识别人物并关联轨迹", "选择人物并核对出镜", "合成人物视频"),
        "speaker_edit": ("区分匿名说话人", "选择目标说话人", "生成发言视频"),
    }
    search_label, review_label, render_label = workflow_terms.get(
        workflow_kind, workflow_terms["content_search"],
    )
    detailed_steps = [
        {"id": "source", "label": "读取素材"},
        *({"id": f"capability_{value}", "label": labels[value]} for value in allowed if value in labels),
        {"id": "search", "label": search_label},
        {"id": "review", "label": review_label},
        {"id": "render", "label": render_label},
    ]
    phase_order = {"prepare": 0, "search": 1, "review": 2, "render": 3, "complete": 4}
    current = phase_order.get(phase, 0)
    capability_stages = {
        "content_transcription": "speech",
        "speech_recognition": "speech",
        "speech_analysis": "speech",
        "content_dialogue_index": "speech",
    }
    current_capability = str(job.get("currentCapability") or "") or capability_stages.get(stage)
    if stage in {"content_sampling", "content_indexing", "content_recognition"}:
        current_capability = next((value for value in allowed if value not in processed), None)
    for item in detailed_steps:
        if item["id"].startswith("capability_") and phase == "search":
            capability = item["id"].removeprefix("capability_")
            item["state"] = (
                # The current stage wins over an older completed snapshot.
                # This matters when a forced/recovered rebuild is actively
                # refreshing a capability that existed in the prior index.
                "current" if capability == current_capability
                else "complete" if capability in processed
                else "pending"
            )
            continue
        if item["id"] == "source" and phase != "prepare":
            item["state"] = "complete"
            continue
        if item["id"] == "search" and phase == "search":
            item["state"] = (
                "current"
                if stage in {
                    "content_index_ready", "content_search", "content_person_description",
                    "content_active_speaker", "content_refinement",
                }
                else "pending"
            )
            continue
        step_phase = (
            "prepare" if item["id"] == "source" else
            "review" if item["id"] == "review" else
            "render" if item["id"] == "render" else "search"
        )
        position = phase_order[step_phase]
        item["state"] = "complete" if phase == "complete" or position < current else "current" if position == current else "pending"
    discovery = job.get("voiceDiscovery") if isinstance(job.get("voiceDiscovery"), dict) else {}
    discovery_status = str(discovery.get("status") or "not_started")
    if workflow_kind == "speaker_edit" and discovery_status in {"not_started", "failed", "cancelled", "ready"} and not search.get("id"):
        state = "action_required"
        action_required = {
            "kind": "select_speaker" if discovery_status == "ready" else "start_speaker_discovery",
            "title": "选择目标说话人" if discovery_status == "ready" else "开始区分说话人",
            "message": "试听代表片段后，选择要保留发言的说话人。" if discovery_status == "ready" else "系统会先按声音区分匿名说话人。",
            "blocking": True,
        }
    elif workflow_kind == "person_edit" and phase == "review" and not search.get("candidates") and action_required is None:
        state = "action_required"
        action_required = {
            "kind": "select_person", "title": "选择目标人物",
            "message": "请从画面人物卡片中选择要提取全部出镜的人物。", "blocking": True,
        }
    elif phase == "review" and search.get("id") and action_required is None:
        state = "action_required"
        review_titles = {
            "content_search": "确认内容片段",
            "person_edit": "核对人物出镜片段",
            "speaker_edit": "核对说话人发言片段",
        }
        action_required = {
            "kind": "review_content",
            "title": review_titles.get(workflow_kind, "确认内容片段"),
            "message": "预览并调整片段边界，确认后再生成视频。",
            "blocking": True,
        }
    return {
        "schemaVersion": 2,
        "mode": "content_extract",
        "kind": workflow_kind,
        "phase": phase,
        "state": state,
        "steps": detailed_steps,
        "actionRequired": action_required,
    }


def workflow_snapshot(job: dict[str, Any]) -> dict[str, Any]:
    """Expose one four-workflow state machine to every presentation surface."""
    kind = workflow_kind_for_job(job)
    if kind != "highlight":
        return content_workflow_snapshot(job) or {
            "schemaVersion": 2, "mode": "content_extract", "kind": kind,
            "phase": "prepare", "state": "running", "steps": [], "actionRequired": None,
        }
    status = str(job.get("status") or "")
    stage = str(job.get("stage") or "queued")
    execution = execution_snapshot(job)
    outputs = job_output_count(job)
    if outputs or status == "completed":
        phase, state = "complete", "ready"
    elif stage in {"rendering", "render", "edit_planning", "alternative_planning", "auto_composition"} or execution.get("operation") in {"render", "auto_composition", "quality_review"}:
        phase, state = "render", "running"
    elif status == AWAITING_CONFIRMATION:
        phase, state = "review", "action_required"
    elif stage not in {"queued", "starting", "probing"}:
        phase, state = "analysis", "running"
    else:
        phase, state = "prepare", "running"
    if status in {"failed", "cancelled"}:
        state = "failed"
    steps = [
        {"id": "source", "label": "读取素材", "state": "current"},
        {"id": "analysis", "label": "理解事件与镜头", "state": "pending"},
        {"id": "review", "label": "编排高光方案", "state": "pending"},
        {"id": "render", "label": "生成高光成片", "state": "pending"},
    ]
    order = {"prepare": 0, "analysis": 1, "review": 2, "render": 3, "complete": 4}
    current = order.get(phase, 0)
    for index, item in enumerate(steps):
        item["state"] = "complete" if phase == "complete" or index < current else "current" if index == current else "pending"
    action_required = None
    if status == AWAITING_CONFIRMATION:
        action_required = {
            "kind": "review_highlights", "title": "审核事件镜头",
            "message": "确认用于成片的事件与镜头后继续。", "blocking": True,
        }
    return {
        "schemaVersion": 2, "mode": "highlight", "kind": kind,
        "phase": phase, "state": state, "steps": steps, "actionRequired": action_required,
    }


def workflow_presentation_snapshot(job: dict[str, Any]) -> dict[str, Any]:
    """Canonical UI contract shared by the task list, workspace and poller."""
    workflow = workflow_snapshot(job)
    execution = execution_snapshot(job)
    kind = str(workflow.get("kind") or workflow_kind_for_job(job))
    action = workflow.get("actionRequired") if isinstance(workflow.get("actionRequired"), dict) else None
    action_kind = str((action or {}).get("kind") or execution.get("actionRequired") or "")
    action_labels = {
        "confirm_brief": "确认剪辑要求",
        "resolve_model_stage": "处理模型异常",
        "review_highlights": "审核高光事件",
        "review_content": "确认内容片段",
        "start_speaker_discovery": "开始区分说话人",
        "select_speaker": "选择目标说话人",
        "select_person": "选择目标人物",
        "coverage_incomplete": "检查未完成的分析",
    }
    if action_kind:
        primary_action = {
            "kind": action_kind,
            "label": action_labels.get(action_kind) or str((action or {}).get("title") or "继续处理"),
            "blocking": bool((action or {}).get("blocking", True)),
        }
    elif execution.get("active"):
        primary_action = {
            "kind": "view_progress",
            "label": "查看处理进度",
            "blocking": False,
        }
    elif execution.get("outcome") == "output_ready":
        primary_action = {
            "kind": "view_outputs",
            "label": "查看成片版本",
            "blocking": False,
        }
    else:
        primary_action = None

    vocabulary = {
        "highlight": {
            "result": "高光成片", "candidate": "事件镜头", "review": "事件审核",
        },
        "content_search": {
            "result": "内容视频", "candidate": "匹配片段", "review": "片段确认",
        },
        "person_edit": {
            "result": "人物剪辑", "candidate": "出镜片段", "review": "出镜核对",
        },
        "speaker_edit": {
            "result": "发言视频", "candidate": "发言片段", "review": "发言核对",
        },
    }.get(kind, {})
    raw_error = job.get("error")
    error = None
    if raw_error:
        stored = raw_error if isinstance(raw_error, dict) else {}
        error = {
            "code": str(stored.get("code") or "job_failed"),
            "message": str(stored.get("message") or stored.get("detail") or raw_error)[:1000],
            "recoveryAction": str(stored.get("recoveryAction") or "retry"),
            "requestId": str(stored.get("requestId") or ""),
        }
    presentation = {
        "schemaVersion": 3,
        "workflowKind": kind,
        "phase": workflow.get("phase"),
        "state": workflow.get("state"),
        "currentStep": next(
            (str(item.get("id") or "") for item in workflow.get("steps") or [] if item.get("state") == "current"),
            None,
        ),
        "steps": copy.deepcopy(workflow.get("steps") or []),
        "actionRequired": copy.deepcopy(action),
        "primaryAction": primary_action,
        "progress": copy.deepcopy(execution.get("progress") or {}),
        "capabilities": copy.deepcopy(execution.get("capabilities") or {}),
        "terminology": vocabulary,
        "error": error,
    }
    presentation.update(ui_presentation_snapshot(
        job,
        workflow=workflow,
        execution=execution,
        output_count=job_output_count(job),
    ))
    return presentation


def _content_ui_revision(job: dict[str, Any]) -> str:
    """Stable digest for content UI changes that progress-only polling must notice."""
    def search_fact(search: Any) -> Any:
        if not isinstance(search, dict):
            return None
        return {
            "id": search.get("id"), "status": search.get("status"),
            "updatedAt": search.get("updatedAt"), "candidateCount": len(search.get("candidates") or []),
            "candidates": [
                [
                    item.get("id"), item.get("start"), item.get("end"),
                    item.get("reviewStatus"), item.get("selected"), item.get("confidenceTier"),
                ]
                for item in search.get("candidates") or [] if isinstance(item, dict)
            ],
            "reviewDraft": search.get("reviewDraft"), "dialogueMode": search.get("dialogueMode"),
            "scanProgress": search.get("scanProgress"),
        }
    payload = {
        "current": search_fact(job.get("contentSearch")),
        "pending": search_fact(job.get("pendingContentSearch")),
        "history": [
            [item.get("id"), item.get("status"), item.get("updatedAt"), len(item.get("candidates") or [])]
            for item in job.get("contentSearchHistory") or [] if isinstance(item, dict)
        ],
        "basket": job.get("contentSelectionBasket"),
        "outputs": [
            [item.get("id"), item.get("contentSearchId"), len(item.get("outputs") or [])]
            for item in job.get("outputVersions") or [] if isinstance(item, dict)
        ],
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:16]


def workflow_kind_for_job(job: dict[str, Any]) -> str:
    """Return the four-way product workflow while preserving old job files."""
    request = job.get("request") if isinstance(job.get("request"), dict) else {}
    # The request records the workflow explicitly chosen in the four-way
    # selector.  A later generic intent-routing snapshot used to overwrite the
    # denormalized top-level value with ``content_search``.  Prefer the durable
    # user choice so persisted person/speaker jobs cannot silently change mode.
    requested = str(request.get("workflowKind") or "").strip().lower()
    if requested in {"highlight", "content_search", "person_edit", "speaker_edit"}:
        return requested
    explicit = str(job.get("workflowKind") or "").strip().lower()
    if explicit in {"highlight", "content_search", "person_edit", "speaker_edit"}:
        return explicit
    entry = str(request.get("entryWorkflow") or "").strip().lower()
    if entry == "voice_discovery":
        return "speaker_edit"
    if entry == "person_discovery":
        return "person_edit"
    return "content_search" if str(job.get("taskMode") or "highlight") == "content_extract" else "highlight"


def content_candidate_events(
    candidates: list[dict[str, Any]], workflow_kind: str,
) -> list[dict[str, Any]]:
    """Build a review-only event layer without changing durable match IDs.

    Person and speaker recognition naturally produces several discontinuous
    intervals for one real-world event.  Confirmation and rendering still work
    with the original candidates; this view groups nearby intervals so the UI
    can present the event first and let the user expand its exact child clips.
    """
    kind = str(workflow_kind or "")
    if kind not in {"person_edit", "speaker_edit"}:
        return []
    max_gap = 3.0 if kind == "person_edit" else 8.0
    ordered = sorted(
        (copy.deepcopy(item) for item in candidates if isinstance(item, dict) and item.get("id")),
        key=lambda item: (float(item.get("start") or 0), float(item.get("end") or 0)),
    )
    groups: list[dict[str, Any]] = []
    for candidate in ordered:
        people = sorted({str(value) for value in candidate.get("matchedPersonIds") or [] if str(value)})
        speaker = str(candidate.get("speaker") or candidate.get("speakerRef") or "").strip()
        subject_key = "|".join(people) if kind == "person_edit" else speaker.casefold()
        if not subject_key:
            subject_key = str(candidate.get("title") or "未标记对象").strip().casefold()
        start = float(candidate.get("start") or 0)
        end = max(start, float(candidate.get("end") or start))
        previous = groups[-1] if groups else None
        if (
            previous is not None
            and previous["_subjectKey"] == subject_key
            and start - float(previous["end"]) <= max_gap
        ):
            group = previous
            group["end"] = round(max(float(group["end"]), end), 3)
        else:
            label = str(candidate.get("speaker") or "").strip()
            if kind == "person_edit":
                labels = [str(value) for value in candidate.get("matchedPersonLabels") or [] if str(value)]
                label = "、".join(labels) or str(candidate.get("title") or "人物出镜")
            group = {
                "_subjectKey": subject_key,
                "kind": "person_appearance" if kind == "person_edit" else "speaker_turns",
                "title": label or ("人物出镜" if kind == "person_edit" else "说话人发言"),
                "start": round(start, 3), "end": round(end, 3),
                "matchIds": [], "segments": [],
            }
            groups.append(group)
        duration = max(0.0, end - start)
        group["matchIds"].append(str(candidate["id"]))
        group["segments"].append({
            "id": str(candidate["id"]), "start": round(start, 3), "end": round(end, 3),
            "duration": round(duration, 3), "title": str(candidate.get("title") or "匹配片段"),
            "confidenceTier": str(candidate.get("confidenceTier") or "reliable"),
            "reviewStatus": str(candidate.get("reviewStatus") or ""),
        })
    for position, group in enumerate(groups, 1):
        raw_id = f"{kind}:{group['_subjectKey']}:{group['start']:.3f}:{group['end']:.3f}"
        group["id"] = f"review_event_{hashlib.sha1(raw_id.encode('utf-8')).hexdigest()[:12]}"
        group["number"] = position
        group["segmentCount"] = len(group["segments"])
        group["clipDuration"] = round(sum(float(item["duration"]) for item in group["segments"]), 3)
        group["sourceSpanDuration"] = round(max(0.0, float(group["end"]) - float(group["start"])), 3)
        group["requiresReview"] = any(
            item.get("confidenceTier") == "possible" or item.get("reviewStatus") == "pending"
            for item in group["segments"]
        )
        group.pop("_subjectKey", None)
    return groups


def source_project_id_for_job(job: dict[str, Any]) -> str:
    """Stable public identity shared by every task derived from one asset."""
    source_hash = str(job.get("sourceHash") or "").strip()
    if source_hash:
        digest = hashlib.sha256(source_hash.encode("utf-8")).hexdigest()[:16]
        return f"asset_{digest}"
    return f"asset_{str(job.get('id') or 'unknown')}"


@lru_cache(maxsize=512)
def _output_media_dimensions(path: str, mtime_ns: int, size: int) -> dict[str, int]:
    """Probe a legacy artifact once per file revision, never assume source dimensions."""
    try:
        info = probe_video(Path(path), settings.ffprobe)
        return {"width": info.width, "height": info.height}
    except Exception:
        return {}


def public_job(job: dict[str, Any]) -> dict[str, Any]:
    # Serialization must never migrate or rename the durable in-memory job.
    # Startup normalization owns persisted changes; response shaping works on
    # an isolated snapshot so a GET request cannot mutate application state.
    job = copy.deepcopy(job)
    normalize_output_versions(job)
    apply_output_naming(job)
    if job.get("id"):
        job["operations"] = [public_render_operation(task, job) for task in render_task_store.for_job(str(job["id"]))]
    # Give legacy manually-created timeline groups stable, distinguishable
    # names instead of repeating the old generic label.
    manual_index = 0
    for group in job.get("eventGroups", []):
        if group.get("assemblyStrategy") != "manual":
            continue
        manual_index += 1
        if str(group.get("title") or "").strip() in {"时间轴选区高光", "手动事件高光", "时间轴片段", "时间轴选区"}:
            group["title"] = f"手动高光片段 {manual_index:02d}"
    visible = {
        key: value for key, value in job.items()
        if key not in {
            "sourcePath", "workDirectory", "outputDirectory", "sourceHash", "analysisCacheKey",
            "temporaryVoiceSessions", "analysisOperation",
            "personMergeHistory", "voiceSpeakerEditHistory",
            # The graph can contain hundreds of facts.  The workspace receives
            # only its summary; evidence for a selected time range is fetched
            # explicitly from the evidence endpoint below.
            "evidenceGraph",
        }
    }
    visible["projectSettings"] = {"outputAspect": "source", "outputFit": "blur", **(job.get("projectSettings") or {})}
    if isinstance(job.get("coverDraft"), dict):
        draft = job["coverDraft"]
        visible["coverDraft"] = {
            key: copy.deepcopy(value) for key, value in draft.items()
            if key not in {"candidates", "variants"}
        }
        visible["coverDraft"]["candidates"] = [
            _public_cover_artifact(str(job.get("id") or ""), item)
            for item in draft.get("candidates") or [] if isinstance(item, dict)
        ]
        visible["coverDraft"]["variants"] = [
            _public_cover_artifact(str(job.get("id") or ""), item)
            for item in draft.get("variants") or [] if isinstance(item, dict)
        ]
    if isinstance(job.get("coverVersions"), list):
        visible["coverVersions"] = [
            _public_cover_artifact(str(job.get("id") or ""), item)
            for item in job.get("coverVersions") or [] if isinstance(item, dict)
        ]
    draft_title = str((job.get("coverDraft") or {}).get("titleText") or "").strip()
    current_cover_id = str(job.get("currentCoverVersionId") or "")
    current_cover = next((
        item for item in job.get("coverVersions") or []
        if isinstance(item, dict) and str(item.get("id") or "") == current_cover_id
    ), None)
    visible["coverNeedsRegeneration"] = bool(
        draft_title and (
            not current_cover
            or str(current_cover.get("titleText") or "").strip() != draft_title
            or not current_cover.get("titleLines")
        )
    )
    visible["editSessions"] = []
    for session in job.get("editSessions") or []:
        if not isinstance(session, dict):
            continue
        public_session = public_edit_session(session)
        if (
            str(session.get("previewStatus") or "") == "ready"
            and str(session.get("previewFingerprint") or "")
            != _edit_session_preview_fingerprint(job, session)
        ):
            # Legacy previews were allowed to claim subtitles/text based only
            # on metadata.  Never expose them as current after the renderer
            # contract changes; the next preview request will rebuild them.
            public_session.update({
                "previewStatus": "stale",
                "previewUrl": None,
                "previewOverlayVerification": {},
            })
        visible["editSessions"].append(public_session)
    active_edit_session_id = str(job.get("activeEditSessionId") or "")
    visible["activeEditSession"] = next(
        (
            copy.deepcopy(session)
            for session in visible["editSessions"]
            if str(session.get("id") or "") == active_edit_session_id
        ),
        None,
    )
    visible["workflowKind"] = workflow_kind_for_job(job)
    visible["personMergeRevision"] = int(job.get("personMergeRevision") or 0)
    visible["personMergeCanUndo"] = bool(job.get("personMergeHistory"))
    visible["sourceProjectId"] = source_project_id_for_job(job)
    visible["contentUiRevision"] = _content_ui_revision(job)
    visible["contentSearchSession"] = content_search_session_snapshot(job)
    if str(job.get("taskMode") or "highlight") != "content_extract":
        # Raw scene-change and waveform peaks are internal recall signals.
        # Filter both current metadata and legacy persisted labels at the API
        # boundary so no client can mistake them for editable events.
        public_groups = [
            group for group in visible.get("eventGroups") or []
            if isinstance(group, dict) and event_group_is_semantic(group)
        ]
        public_group_ids = {str(group.get("id")) for group in public_groups}
        public_candidates = [
            candidate for candidate in visible.get("candidates") or []
            if isinstance(candidate, dict) and candidate_is_semantic(candidate)
        ]
        visible["eventGroups"] = public_groups
        visible["recommendedGroupIds"] = [
            value for value in visible.get("recommendedGroupIds") or []
            if str(value) in public_group_ids
        ]
        visible["candidates"] = public_candidates
        public_candidate_indices = {str(candidate.get("index")) for candidate in public_candidates}
        visible["recommendedIndices"] = [
            value for value in visible.get("recommendedIndices") or []
            if str(value) in public_candidate_indices
        ]
        visible["eventGroupCount"] = len(public_groups)
        visible["recommendedCount"] = len(visible["recommendedGroupIds"])
        visible["candidateCount"] = len(public_candidates)
        if (job.get("eventGroups") or job.get("candidates")) and not (public_groups or public_candidates):
            visible["semanticReanalysisRequired"] = True
            visible["detail"] = "旧版分析只保留了未确认的画面或声音变化信号，请重新分析以生成具体高光事件"
    if str(job.get("taskMode") or "") == "content_extract":
        order_mode = str((job.get("contentSearch") or {}).get("orderMode") or "source")
        order_text = "按源视频时间顺序" if order_mode == "source" else "按确认顺序"
        public_messages = copy.deepcopy(visible.get("messages") or [])
        for message in public_messages:
            text = str(message.get("text") or "")
            text = re.sub(
                r"已保存为 V(\d+)：将 \d+ 个高光事件、(\d+) 个镜头合成为 1 条视频。\s*",
                lambda match: f"已保存为 V{match.group(1)}：{order_text}将 {match.group(2)} 个已确认内容片段合成为 1 条视频。",
                text,
            )
            text = re.sub(
                r"已保存为 V(\d+)：分别导出 (\d+) 条事件视频，共组合 \d+ 个精彩镜头。",
                r"已保存为 V\1：已分别导出 \2 个确认内容片段。",
                text,
            )
            text = text.replace(
                "重新选择已经分析好的镜头并合成",
                "重新选择已经检索到的内容片段",
            )
            if "已返回事件审核" in text:
                text = "已返回内容片段确认。可以重新选择检索结果并生成新版本；已有版本仍可预览和下载，也不会再次分析视频。"
            if text.startswith("可以说“单条成片目标改成"):
                text = "这条查找请求当时被旧路由误判，尚未执行。请重新发送查找条件；现在会直接进入内容检索。"
            message["text"] = text
        visible["messages"] = public_messages
        visible["detail"] = _content_public_detail(job)
        public_groups = copy.deepcopy(visible.get("eventGroups") or [])
        query = str(((visible.get("contentSearch") or {}).get("intent") or {}).get("query") or (visible.get("contentSearch") or {}).get("instruction") or "匹配内容").strip()
        for position, group in enumerate(public_groups, 1):
            group["groupKind"] = "content_match"
            if str(group.get("title") or "").strip() in {"同时满足全部检索条件", "满足检索条件的片段"}:
                group["title"] = f"{query[:72]} · 第 {position} 段"
            group["summary"] = _dedupe_content_text(group.get("summary") or "与查找条件匹配的内容")
            for segment in group.get("segments") or []:
                if isinstance(segment, dict):
                    segment["segmentKind"] = "content_match"
                    segment["reason"] = _dedupe_content_text(segment.get("reason"))
        visible["eventGroups"] = public_groups
    if isinstance(visible.get("contentSearch"), dict):
        public_search = _normalize_active_speaker_clarification(
            visible, copy.deepcopy(visible["contentSearch"]),
        )
        public_candidates = [item for item in public_search.get("candidates") or [] if isinstance(item, dict)]
        public_stats = public_search.setdefault("retrievalStats", {})
        if public_stats.get("evidenceHitCount") is None:
            public_stats["evidenceHitCount"] = len({
                str(reference.get("id") if isinstance(reference, dict) else reference)
                for candidate in public_candidates
                for reference in candidate.get("evidenceRefs") or []
                if str(reference.get("id") if isinstance(reference, dict) else reference)
            })
        execution = public_search.get("executionPlan") if isinstance(public_search.get("executionPlan"), dict) else {}
        coverage_manifest = execution.get("coverageManifest") if isinstance(execution.get("coverageManifest"), dict) else {}
        required_operations = set(execution.get("requiredOperations") or public_stats.get("requiredOperations") or [])
        legacy_active_speaker_coverage = (
            "person.active_speaker_link" in required_operations
            and str(coverage_manifest.get("schemaVersion") or "") != "coverage-manifest-v3"
        )
        if legacy_active_speaker_coverage:
            warning = "这项人物发言结果来自旧版覆盖记录，不能据此断言全片没有遗漏；重新发送同一查找条件即可使用当前主动说话人模型复检。"
            execution = copy.deepcopy(execution)
            execution["warnings"] = list(dict.fromkeys([*(execution.get("warnings") or []), warning]))
            execution["failedOperations"] = list(dict.fromkeys([
                *(execution.get("failedOperations") or []), "person.active_speaker_link",
            ]))
            public_search["executionPlan"] = execution
            public_search["coverageComplete"] = False
            public_search["coverageStatus"] = "partial"
            public_stats["coverageComplete"] = False
            for candidate in public_candidates:
                candidate["requiresReview"] = True
                candidate["reviewReasons"] = list(dict.fromkeys([
                    *(candidate.get("reviewReasons") or []), "主动说话人覆盖记录需要按当前模型复检",
                ]))
        for candidate in public_candidates:
            decision = candidate.get("decision") if isinstance(candidate.get("decision"), dict) else {}
            tier = str(candidate.get("confidenceTier") or "")
            if tier not in {"reliable", "possible"}:
                tier = "possible" if (
                    decision.get("reviewRequired")
                    or candidate.get("requiresReview")
                    or not candidate.get("calibrated", False)
                ) else "reliable"
            candidate["confidenceTier"] = tier
            review_status = str(candidate.get("reviewStatus") or "")
            review_required = tier == "possible" and review_status not in {"kept", "rejected"}
            candidate["requiresReview"] = review_required
            candidate["decision"] = {
                **copy.deepcopy(decision),
                "confidenceTier": tier,
                "reviewRequired": review_required,
                "reviewReasons": (
                    list(decision.get("reviewReasons") or []) if review_required else []
                ),
            }
        legacy_titles = {"同时满足全部检索条件", "满足检索条件的片段"}
        for candidate in public_candidates:
            if str(candidate.get("title") or "").strip() not in legacy_titles:
                continue
            speaker_evidence = candidate.get("activeSpeakerEvidence") if isinstance(candidate.get("activeSpeakerEvidence"), dict) else {}
            person_label = str(speaker_evidence.get("personLabel") or "").strip()
            query = str((public_search.get("intent") or {}).get("query") or public_search.get("instruction") or "").strip()
            candidate["title"] = f"{person_label}发言" if person_label else query[:80] or "匹配片段"
        title_groups: dict[str, list[dict[str, Any]]] = {}
        for candidate in public_candidates:
            title_groups.setdefault(str(candidate.get("title") or "匹配片段"), []).append(candidate)
        for title, candidates in title_groups.items():
            if len(candidates) <= 1 or any(" · 第 " in str(item.get("title") or "") for item in candidates):
                continue
            for position, candidate in enumerate(sorted(candidates, key=lambda item: float(item.get("start") or 0)), 1):
                candidate["title"] = f"{title} · 第 {position} 段"[:100]
        public_search["candidates"] = public_candidates
        public_search["candidateEvents"] = content_candidate_events(
            public_candidates, workflow_kind_for_job(job),
        )
        public_search["coverage"] = content_search_coverage_snapshot(public_search)
        public_search["interactionState"] = _content_interaction_state(visible, public_search)
        visible["contentSearch"] = public_search
        records = []
        for record in _content_search_records(job):
            if str(record.get("id") or "") == str(public_search.get("id") or ""):
                current_record = copy.deepcopy(public_search)
                current_record["candidateDetailsLoaded"] = True
                records.append(current_record)
            else:
                pending_id = str((job.get("pendingContentSearch") or {}).get("id") or "")
                records.append(
                    _pending_content_search_public_summary(job, record)
                    if str(record.get("id") or "") == pending_id
                    else _content_search_public_summary(record)
                )
        visible["contentSearchRecords"] = records
        visible["contentSearchHistory"] = [
            copy.deepcopy(record) for record in records
            if str(record.get("id") or "") != str(public_search.get("id") or "")
        ]
    if isinstance(visible.get("pendingEditProposal"), dict):
        visible["pendingEditProposal"] = {
            key: value for key, value in visible["pendingEditProposal"].items()
            if key != "_previewWorkspace"
        }
    auto_job = isinstance(job.get("autoComposition"), dict) and bool(job.get("autoComposition", {}).get("versions"))
    auto_plan_labels = [str(item.get("label") or "") for item in (job.get("autoPlans") or [])]
    def legacy_auto_meta(index: int) -> dict[str, str] | None:
        if not auto_job:
            return None
        if index == 0:
            return auto_composition_meta("vlm")
        return auto_composition_meta("llm", auto_plan_labels[index - 1] if index - 1 < len(auto_plan_labels) else "")

    def public_outputs(items: list[dict[str, Any]], version_meta: dict[str, Any] | None = None) -> list[dict[str, Any]]:
        result = []
        output_count = len(items)
        for position, item in enumerate(items, 1):
            item = dict(item)
            if job.get("outputDirectory") and (not item.get("width") or not item.get("height")):
                directory = Path(job["outputDirectory"]).resolve()
                filename = str(item.get("filename") or "")
                media_path = (directory / filename).resolve()
                if filename and media_path.parent == directory and media_path.is_file():
                    try:
                        stat = media_path.stat()
                        item.update(_output_media_dimensions(str(media_path), stat.st_mtime_ns, stat.st_size))
                    except OSError:
                        pass  # A concurrent cleanup may remove an artifact during serialization.
            source_version = next((version for version in job.get("outputVersions") or []
                                   if any(output.get("filename") == item.get("filename")
                                          for output in version.get("outputs") or [])), version_meta or {})
            metadata = {**(version_meta or {}), **item}
            naming = build_output_naming(
                job, source_version or version_meta or {}, item,
                position=position, output_count=output_count,
            )
            editing_explanation = build_output_editing_explanation(job, item, metadata)
            public_item = {
                **item,
                **({key: version_meta[key] for key in ("strategyKey", "displayName", "sourceLabel", "strategyDescription") if key in version_meta} if version_meta else {}),
                **naming,
                "videoUrl": f"/api/jobs/{job['id']}/outputs/{item['filename']}",
                "previewUrl": (
                    f"/api/jobs/{job['id']}/outputs/{item['filename']}"
                    if item.get("previewOnly") else f"/api/jobs/{job['id']}/outputs/{item['filename']}/preview"
                ),
                "previewReady": bool(item.get("previewOnly")) or output_preview_path(job, str(item["filename"])).is_file(),
                "downloadUrl": f"/api/jobs/{job['id']}/outputs/{item['filename']}?download=1",
                "editingExplanation": editing_explanation,
                "outputRevision": output_revision(source_version, item),
                "capabilities": output_capabilities(job, source_version, item),
            }
            if item.get("coverVersionId"):
                public_item.update({
                    "coverUrl": f"/api/jobs/{job['id']}/outputs/{item['filename']}/cover",
                    "packageUrl": f"/api/jobs/{job['id']}/outputs/{item['filename']}/package",
                    "coverIntroAvailable": not bool(
                        item.get("previewOnly") or (version_meta or {}).get("previewOnly") or item.get("coverIntro")
                    ),
                })
            if str(job.get("taskMode") or "") == "content_extract" and not item.get("socialReframe"):
                public_item.update({
                    "outputKind": "content_video",
                    "strategyKey": "content_extract",
                    "title": "内容视频",
                    "reason": "由用户审核确认的内容片段按指定顺序生成",
                })
                public_item["segments"] = [
                    {
                        **segment,
                        "segmentKind": "content_match",
                        "reason": _dedupe_content_text(segment.get("reason")),
                    }
                    for segment in public_item.get("segments") or [] if isinstance(segment, dict)
                ]
            else:
                normalize_output_event_hierarchy(public_item, list(job.get("eventGroups") or []))
            result.append(public_item)
        return result
    if visible.get("agentPreviewOutputs"):
        visible["agentPreviewOutputs"] = public_outputs(
            [
                item for item in visible.get("agentPreviewOutputs") or []
                if isinstance(item, dict)
            ],
            {"number": 0, "displayName": "Agent 审核预览", "previewOnly": True},
        )
    quality_loop_v3 = str(job.get("analysisPipelineVersion") or "") == PIPELINE_VERSION
    automatic_quality_review = bool(
        isinstance(job.get("autoComposition"), dict)
        and (job["autoComposition"].get("status") or job["autoComposition"].get("phase"))
    )
    current_version = find_output_version(job, job.get("currentOutputVersionId"))
    current_preview_pending = bool(
        quality_loop_v3 and automatic_quality_review and current_version and current_version.get("previewOnly")
        and not current_version.get("manualReviewRequired")
        and not (
            isinstance(current_version.get("qualityGate"), dict)
            and current_version["qualityGate"].get("passed") is True
        )
    )
    if visible.get("outputs"):
        visible["outputs"] = [] if current_preview_pending else public_outputs(visible["outputs"])
    if visible.get("outputVersions"):
        normalized_versions = []
        visible_versions = [
            version for version in visible["outputVersions"]
            if not (
                quality_loop_v3 and automatic_quality_review and version.get("previewOnly")
                and not version.get("manualReviewRequired")
                and not (
                    isinstance(version.get("qualityGate"), dict)
                    and version["qualityGate"].get("passed") is True
                )
            )
        ]
        for index, version in enumerate(visible_versions):
            version_meta = {"number": version.get("number")}
            version_meta.update({
                key: version[key]
                for key in (
                    "strategyKey", "displayName", "sourceLabel", "strategyDescription",
                    "recommended", "recommendationReason", "reviewStatus", "reviewReport",
                    "qualityGate", "qualityStatus", "variantKind", "generationBatchId",
                    "sourceVersionId", "masterReady", "previewOnly",
                    "editorialNarrative", "orderMode", "orderReason", "parentVersionId",
                    "contentSearchInstruction",
                )
                if version.get(key) is not None
            })
            if not any(version_meta.values()):
                version_meta = legacy_auto_meta(index) or {}
            normalized_versions.append({
                **version,
                **version_meta,
                "outputs": public_outputs(version.get("outputs", []), version_meta),
                "previewOutputs": public_outputs(version.get("previewOutputs", []), {**version_meta, "previewOnly": True}),
            })
        visible["outputVersions"] = normalized_versions
    if isinstance(visible.get("autoComposition"), dict):
        public_auto = {
            key: value for key, value in visible.get("autoComposition", {}).items()
            if key not in {"rejectedVersions"}
        }
        versions = list(public_auto.get("versions") or [])
        normalized_auto_versions = []
        for index, version in enumerate(versions):
            if isinstance(version, dict) and version.get("displayName"):
                normalized_auto_versions.append(version)
            else:
                label = str(version or "")
                normalized_auto_versions.append(legacy_auto_meta(index) or auto_composition_meta("llm", label))
        playable_independent = _playable_automatic_versions(job)
        target_count = max(1, min(4, int(
            public_auto.get("plannedVariantCount")
            or (job.get("request") or {}).get("autoVariantCount")
            or 3
        )))
        missing_count = max(0, target_count - len(playable_independent))
        active_auto = str(public_auto.get("status") or "") in {"queued", "running", "cancelling"}
        recovery = {
            "canRegenerateMissingVariants": bool(
                missing_count and (visible.get("eventGroups") or visible.get("candidates")) and not active_auto
            ),
            "targetVariantCount": target_count,
            "existingVariantCount": len(playable_independent),
            "missingVariantCount": missing_count,
            "reason": "legacy_quality_withdrawal" if missing_count else "complete",
        }
        visible["autoComposition"] = {
            **public_auto, "versions": normalized_auto_versions,
            "recovery": recovery,
        }
    visible["sourceUrl"] = f"/api/jobs/{job['id']}/source"
    visible["previewUrl"] = f"/api/jobs/{job['id']}/preview"
    visible.update(thumbnail_public_fields(job))
    identity = preview_proxy_identity(job)
    proxy = proxy_cache_path(identity)
    visible["previewReady"] = proxy.is_file()
    scheduled = preview_proxy_scheduler.is_scheduled(identity)
    visible["previewPreparing"] = not proxy.is_file() and (
        scheduled or proxy.with_suffix(".tmp.mp4").is_file()
    )
    visible["workflow"] = workflow_snapshot(visible)
    visible["execution"] = execution_snapshot(job)
    visible["presentation"] = workflow_presentation_snapshot(job)
    return visible


def job_output_count(job: dict[str, Any]) -> int:
    versions = job.get("outputVersions") if isinstance(job.get("outputVersions"), list) else []
    if versions:
        return sum(len(version.get("outputs") or []) for version in versions if isinstance(version, dict))
    return len(job.get("outputs") or [])


def public_job_summary(job: dict[str, Any]) -> dict[str, Any]:
    """Small home-card payload; never include review evidence or edit plans."""
    video = job.get("videoInfo") if isinstance(job.get("videoInfo"), dict) else {}
    event_groups = job.get("eventGroups") if isinstance(job.get("eventGroups"), list) else []
    candidates = job.get("candidates") if isinstance(job.get("candidates"), list) else []
    content_search = job.get("contentSearch") if isinstance(job.get("contentSearch"), dict) else {}
    content_review = content_search.get("reviewDraft") if isinstance(content_search.get("reviewDraft"), dict) else {}
    content_candidates = content_search.get("candidates") if isinstance(content_search.get("candidates"), list) else []
    return {
        "id": job["id"],
        "revision": int(job.get("revision") or 0),
        "status": job.get("status"),
        "stage": job.get("stage"),
        "detail": _content_public_detail(job) if job.get("taskMode") == "content_extract" else job.get("detail"),
        "filename": job.get("filename"),
        "taskMode": job.get("taskMode", "highlight"),
        "workflowKind": workflow_kind_for_job(job),
        "sourceProjectId": source_project_id_for_job(job),
        "resolvedTaskKind": job.get("resolvedTaskKind", job.get("taskMode", "highlight")),
        "routingConfidence": job.get("routingConfidence", 1.0),
        "storageMode": job.get("storageMode", "editable"),
        "createdAt": job.get("createdAt"),
        "updatedAt": job.get("updatedAt"),
        "videoInfo": {
            "duration": video.get("duration"),
            "width": video.get("width"),
            "height": video.get("height"),
            "has_audio": video.get("has_audio"),
        },
        "eventGroupCount": len(event_groups),
        "candidateCount": len(content_candidates) if job.get("taskMode") == "content_extract" else len(candidates),
        "outputCount": job_output_count(job),
        "agent": copy.deepcopy(job.get("agent") or None),
        "agentDraft": bool(job.get("agentDraft")),
        "instructionSubmitted": bool(job.get("instructionSubmitted", True)),
        "execution": execution_snapshot(job),
        "presentation": workflow_presentation_snapshot(job),
        "activeChildJobId": job.get("activeChildJobId"),
        "latestHandoff": job.get("latestHandoff"),
        "analysisPipelineVersion": job.get("analysisPipelineVersion"),
        "algorithmVersion": job.get("algorithmVersion"),
        "evidenceSummary": job.get("evidenceSummary"),
        "recognition": job.get("recognition") if job.get("taskMode") == "content_extract" else None,
        **thumbnail_public_fields(job),
        "workflow": workflow_snapshot(job),
    }


