def run_auto_variant_render(job_id: str, selection_keys: list[Any], output_mode: str, count: int) -> None:
    profiles = [("complete", "叙事完整"), ("tight", "节奏紧凑"), ("climax", "高潮优先"), ("complete", "信息密度")][:max(2, min(5, count))]
    for index, (mode, label) in enumerate(profiles):
        with jobs_lock:
            if job_id not in jobs:
                return
            if index:
                cancel_events[job_id] = threading.Event()
            jobs[job_id].update({"status": "running", "stage": "rendering", "progress": round(.82 + .16 * index / len(profiles), 3), "stageProgress": round(index / max(1, len(profiles)), 4), "detail": f"正在生成自动版本 {index + 1}/{len(profiles)} · {label}", "error": None})
            target = float(jobs[job_id].get("totalTargetSeconds") or jobs[job_id].get("request", {}).get("totalTargetSeconds") or 0)
            if jobs[job_id].get("eventGroups"):
                jobs[job_id]["confirmedSegmentIds"] = _choose_auto_segment_ids(jobs[job_id], selection_keys, mode, target)
            save_job(jobs[job_id])
        with jobs_lock:
            order_mode = str(jobs[job_id].get("orderMode") or "source")
            brief = jobs[job_id].get("brief") or {}
            subtitle_mode = str(brief.get("subtitlePreference") or jobs[job_id].get("request", {}).get("subtitleMode") or "none")
            subtitle_style = normalize_subtitle_style(brief.get("subtitleStyle") or jobs[job_id].get("request", {}).get("subtitleStyle"))
        run_confirmed_render(job_id, selection_keys, output_mode, "complete", label, finalize_status=index == len(profiles) - 1, subtitle_mode=subtitle_mode, order_mode=order_mode, subtitle_style=subtitle_style)
        with jobs_lock:
            if jobs[job_id].get("status") in {"failed", "cancelled"}:
                break
    with jobs_lock:
        job = jobs.get(job_id)
        if job and job.get("status") == "completed":
            job["detail"] = f"已生成 {len(profiles)} 个自动高光版本，可逐一预览选择"
            save_job(job)


def run_alternative_cut(job_id: str) -> None:
    """Plan and render one meaningfully different cut without another review step."""
    with jobs_lock:
        job = jobs.get(job_id)
        if not job:
            return
        group_ids = [str(value) for value in (
            job.get("confirmedGroupIds")
            or job.get("recommendedGroupIds")
            or [group.get("id") for group in job.get("eventGroups") or []]
        ) if value]
        target = job.get("totalTargetSeconds") or (job.get("request") or {}).get("totalTargetSeconds")
        structure = str((job.get("brief") or {}).get("structure") or "auto")
        previous_outputs = copy.deepcopy(job.get("outputs") or [])
        previous_version_id = job.get("currentOutputVersionId")
    request = AutoPlanRequest(
        scope="all_pool", groupIds=group_ids,
        targetSeconds=float(target) if target not in (None, "", "auto") else None,
        structure=structure, variantCount=3,
    )
    run_auto_plan_generation(job_id, request)
    with jobs_lock:
        job = jobs.get(job_id)
        if not job:
            return
        plans = [plan for plan in job.get("autoPlans") or [] if plan.get("sequence")]
        existing_signatures = [
            automatic_composition_signature(output.get("segments"))
            for version in job.get("outputVersions") or []
            for output in version.get("outputs") or []
            if output.get("segments")
        ]
        distinct = [
            plan for plan in plans
            if (signature := automatic_composition_signature(plan.get("sequence")))
            and all(automatic_composition_similarity(signature, old) < .85 for old in existing_signatures if old)
        ]
        candidates = distinct or plans
        if not candidates:
            job.update({
                "status": "completed", "stage": "completed", "progress": 1.0,
                "detail": "没有找到足够不同且可安全生成的新剪法",
                "currentAction": "当前成片已保留", "outputs": previous_outputs,
                "currentOutputVersionId": previous_version_id, "error": None,
            })
            save_job(job)
            append_message(job_id, "assistant", "没有找到足够不同的新剪法，当前成片保持不变。", kind="notice")
            return
        plan = candidates[0]
        label = str(plan.get("label") or "另一种剪法")
    append_message(job_id, "assistant", f"已选出差异最大的方案“{label}”，正在后台生成新版本。", kind="notice")
    run_confirmed_render(
        job_id, [], "single_reel", "complete", label, True,
        list(plan.get("sequence") or []), label, list(plan.get("chapters") or []),
        "none", "selection", "clean", None, False,
        list(plan.get("cutaways") or []), dict(plan.get("techniquePolicy") or {}),
    )


def _serializable_render_arg(value: Any) -> Any:
    """Convert render arguments into a stable JSON representation."""
    if isinstance(value, BaseModel):
        if hasattr(value, "model_dump"):
            return value.model_dump(mode="json")
        return value.dict()
    if isinstance(value, dict):
        return {str(key): _serializable_render_arg(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_serializable_render_arg(item) for item in value]
    if isinstance(value, Path):
        return str(value)
    return value


def public_render_operation(task: dict[str, Any], job: dict[str, Any]) -> dict[str, Any]:
    result = (job.get("renderOperations") or {}).get(task["id"]) or {}
    return {"operationId": task["id"], "status": task["status"], "error": task.get("error") or result.get("error"),
            "progress": result.get("progress"), "detail": result.get("detail") or "",
            "result": {"versionIds": result.get("resultVersionIds") or []},
            "retryable": task["status"] == "failed" and "export_confirmation_required" not in str(task.get("error")),
            "createdAt": task["createdAt"], "updatedAt": task["updatedAt"]}


def get_render_operation(job_id: str, operation_id: str) -> dict[str, Any]:
    with jobs_lock:
        job = jobs.get(job_id)
        task = render_task_store.get(operation_id)
        if not job or not task or task["jobId"] != job_id:
            raise HTTPException(404, "操作不存在")
        return {"operation": public_render_operation(task, job)}


def run_persisted_render_task(job_id: str, kind: str, raw_args: list[Any]) -> Any:
    """Dispatch one allow-listed render task restored from SQLite."""
    targets = {
        run_automatic_composition.__name__: run_automatic_composition,
        run_missing_auto_variants.__name__: run_missing_auto_variants,
        run_auto_plan_generation.__name__: run_auto_plan_generation,
        run_llm_order_generation.__name__: run_llm_order_generation,
        run_confirmed_render.__name__: run_confirmed_render,
        run_auto_variant_render.__name__: run_auto_variant_render,
        run_alternative_cut.__name__: run_alternative_cut,
        run_edit_session_render.__name__: run_edit_session_render,
        run_agent_review_render.__name__: run_agent_review_render,
        run_agent_review_batch.__name__: run_agent_review_batch,
        run_agent_final_output.__name__: run_agent_final_output,
        run_cover_intro_render.__name__: run_cover_intro_render,
    }
    target = targets.get(str(kind))
    if target is None:
        raise RuntimeError(f"不支持的持久化渲染任务：{kind}")
    args = list(raw_args)
    if target is run_auto_plan_generation and args:
        args[0] = AutoPlanRequest(**dict(args[0]))
    elif target is run_llm_order_generation and args:
        args[0] = LlmOrderRequest(**dict(args[0]))
    operation_id = current_task_id()
    with jobs_lock:
        job = jobs.get(job_id)
        if not job and operation_id:
            raise RuntimeError("任务不存在")
        if operation_id and job:
            job.setdefault("renderOperations", {})[operation_id] = {
                "operationId": operation_id, "kind": kind, "status": "running", "startedAt": now_iso(),
                "selectedVersionId": job.get("currentOutputVersionId"),
                "selectionRevision": int(job.get("outputSelectionRevision") or 0),
                "agentPlanId": (job.get("agent") or {}).get("planId"),
            }
            save_job(job)
    error_text = ""
    try:
        if kind == "run_confirmed_render" and len(args) > 15 and args[15] and len(args) < 20:
            raise RuntimeError("export_confirmation_required：旧导出队列缺少冻结规格，请重新预览确认")
        if operation_id and kind in {"run_edit_session_render", "run_agent_final_output"} and len(args) < 3:
            raise RuntimeError("export_confirmation_required：旧精剪队列缺少冻结规格，请重新预览确认")
        return target(job_id, *args)
    except BaseException as error:
        error_text = str(error)[:2000]
        raise
    finally:
        if operation_id:
            with jobs_lock:
                job = jobs.get(job_id)
                if job:
                    operation = job.setdefault("renderOperations", {}).setdefault(operation_id, {})
                    operation.update({"status": "failed" if error_text else "completed", "error": error_text,
                                      "finishedAt": now_iso(), "resultVersionIds": [
                                          version["id"] for version in job.get("outputVersions") or []
                                          if version.get("operationId") == operation_id]})
                    other_active = any(item["id"] != operation_id and item["status"] in {"queued", "running"}
                                       for item in render_task_store.for_job(job_id))
                    if other_active:
                        job.update({"status": "running", "stage": "rendering", "detail": "仍有其他渲染操作正在进行"})
                    elif "export_confirmation_required" in error_text:
                        job.update({"status": "awaiting_confirmation", "stage": "review", "detail": "旧导出请求需要重新预览确认", "error": error_text})
                    elif job.get("outputs") and not error_text and any(
                        version.get("id") in (operation.get("resultVersionIds") or []) and not version.get("previewOnly")
                        for version in job.get("outputVersions") or []
                    ):
                        job.update({"status": "completed", "stage": "completed", "progress": 1.0, "error": None})
                    save_job(job)


def register_render_future(job_id: str, future: Future[Any]) -> None:
    with jobs_lock:
        render_futures.setdefault(job_id, set()).add(future)

    def forget(completed: Future[Any]) -> None:
        with jobs_lock:
            futures = render_futures.get(job_id)
            if not futures:
                return
            futures.discard(completed)
            if not futures:
                render_futures.pop(job_id, None)

    future.add_done_callback(forget)


def submit_render_task(job_id: str, target: Any, *args: Any, dedup_key: str | None = None) -> Future[Any]:
    """Persist a render task before making it visible to the worker pool."""
    if target.__name__ in {"run_edit_session_render", "run_agent_final_output"} and len(args) == 2:
        with jobs_lock:
            job = jobs[job_id]
            session = find_edit_session(job, str(args[0]))
            if int(session.get("revision") or 0) != int(args[1]):
                raise HTTPException(409, "编辑草稿已变化，请重新确认")
            segments, cutaways = build_edit_session_render_plan(job, session)
            draft_id = session.get("subtitleDraftId") if session.get("subtitleEnabled") else None
            spec = freeze_spec(segments=segments, cutaways=cutaways, text_layers=session.get("textLayers"),
                reframe=_effective_edit_session_reframe(job, session), subtitle_mode="burn" if draft_id else "none",
                subtitle_style=session.get("subtitleStyle") or "clean",
                subtitle_draft=_subtitle_draft_for_job(job, draft_id) if draft_id else None)
            args = (*args, spec)
    serializable_args = [_serializable_render_arg(value) for value in args]
    task_id, future = durable_render_executor.submit(
        job_id=job_id,
        target=run_persisted_render_task,
        args=(job_id, target.__name__, serializable_args),
        dedup_key=dedup_key,
    )
    future.operation_id = task_id
    register_render_future(job_id, future)
    return future


def health() -> dict[str, Any]:
    speech_state = sensevoice_status(settings.data_root / "cache" / "speech-worker" / "status.json")
    active_vision = vision_store.resolve()
    provider_label = vision_provider_label(str(active_vision["provider"]))
    active_llm = resolve_llm_configuration({"llmConfig": llm_store.snapshot(), "visionConfig": vision_store.snapshot()})
    # Keep the health request lightweight. Importing torch and probing CUDA can
    # still block even without TalkNet; detailed capability discovery happens
    # when a job starts, not while the frontend is booting.
    recognition_state = {
        "schemaVersion": RECOGNITION_SCHEMA_VERSION,
        "enabled": bool(getattr(settings, "recognition_enabled", True)),
        "device": "unknown",
        "activeSpeaker": active_speaker_runtime(settings, probe=False),
    }
    return build_health_snapshot(
        settings=settings,
        speech_state=speech_state,
        active_vision=active_vision,
        vision_provider_name=provider_label,
        active_llm=active_llm,
        recognition_state=recognition_state,
        voiceprint_state=voice_profile_store.status(),
    )


